#define MAXN 100005
const ll INF = 1000*1000*1000;

struct rib {
	ll b, u, c, f;
	size_t back;
};

void add_rib (vector < vector<rib> > & g, ll a, ll b, ll u, ll c) {
	rib r1 = { b, u, c, 0, g[b].size() };
	rib r2 = { a, 0, -c, 0, g[a].size() };
	g[a].push_back (r1);
	g[b].push_back (r2);
}
namespace k{
	ll n,m,k,c,d;
}
vector <ll> vr[55];
ll lr[50];
int main()
{
	ll n=50*99+1, m, k=INF;
	vector < vector<rib> > g (n);  //  ***** INITIALISE *****  initialise n in the last
	ll s, t;  					   //  ***** INITIALISE *****  initialise s,t,k
	// ... чтение графа ...

	cin>>k::n>>k::m>>k::k>>k::c>>(k::d);

	ll tim=99;
	rep(i,1,k::k+1)
	{
		cin>>lr[i];
		add_rib(g,0,lr[i],1,0);
	}
	rep(j,0,tim-1)
	{
		rep(i,2,k::n+1)
		add_rib(g,j*50+i,(j+1)*50+i,50,k::c);
	}
	rep(j,1,tim)
	{
		add_rib(g,j*50+1,1,50,0);
	}
	rep(i,0,k::m)
	{
		ll x,y;
		cin>>x>>y;
		vr[x].pb(y);
		vr[y].pb(x);

		rep(j,0,tim-1)
		{
			rep(l,0,50)
			{
				add_rib(g,j*50+x,(j+1)*50+y,1,(k::c)+(k::d)*((l+1)*(l+1)-(l*l)));
				add_rib(g,j*50+y,(j+1)*50+x,1,(k::c)+(k::d)*((l+1)*(l+1)-(l*l)));
			}
		}
	}
	s=0,t=1;


	ll flow = 0,  cost = 0;
	while (flow < k) {
		// cout<<flow<<"A";
		vector<ll> id (n, 0);
		vector<ll> d (n, INF);
		vector<ll> q (n);
		vector<ll> p (n);
		vector<size_t> p_rib (n);
		ll qh=0, qt=0;
		q[qt++] = s;
		d[s] = 0;
		while (qh != qt) {
			// cout<<qh<<" "<<qt<<"  ";
			ll v = q[qh++];
			id[v] = 2;
			if (qh == n)  qh = 0;
			for (size_t i=0; i<g[v].size(); ++i) {
				rib & r = g[v][i];
				if (r.f < r.u && d[v] + r.c < d[r.b]) {
					d[r.b] = d[v] + r.c;
					if (id[r.b] == 0) {
						q[qt++] = r.b;
						if (qt == n)  qt = 0;
					}
					else if (id[r.b] == 2) {
						if (--qh == -1)  qh = n-1;
						q[qh] = r.b;
					}
					id[r.b] = 1;
					p[r.b] = v;
					p_rib[r.b] = i;
				}
			}
		}
		if (d[t] == INF)  break;
		ll addflow = k - flow;
		for (ll v=t; v!=s; v=p[v]) {
			ll pv = p[v];  size_t pr = p_rib[v];
			addflow = min (addflow, g[pv][pr].u - g[pv][pr].f);
		}
		for (ll v=t; v!=s; v=p[v]) {
			ll pv = p[v];  size_t pr = p_rib[v],  r = g[pv][pr].back;
			g[pv][pr].f += addflow;
			g[v][r].f -= addflow;
			cost += g[pv][pr].c * addflow;
		}
		flow += addflow;
	}
	cout<<cost<<"\n";
	// ... вывод результата ...

}

