#include <bits/stdc++.h>
using namespace std;
const int MAX_N = 10000, MAX_M = MAX_N * 100;
const long long INF = LLONG_MAX >> 5;

class FlowNetwork {
private:
    int head[MAX_N], v[MAX_M], nxt[MAX_M], c[MAX_M], ptr, t;
    long long w[MAX_M], cost;
    inline void add_edge(int u, int v, long long w, int c) {
        this->v[ptr] = v; this->w[ptr] = w; this->c[ptr] = c;
        this->nxt[ptr] = head[u]; head[u] = ptr++;
    }
    int dist[MAX_N], id[MAX_N], current[MAX_N]; bool visited[MAX_N];

    bool spfa(int s, int t) {
        memset(visited, 0, sizeof(visited));
        memset(dist, -1, sizeof(dist));
        std::queue<int> q; q.push(s);
        dist[s] = 0; id[s] = 1;
        while (!q.empty()) {
            int node = q.front(); q.pop(); visited[node] = false;
            for (int i = head[node]; i != -1; i = nxt[i]) {
                if (w[i] && (dist[v[i]] == -1 || dist[v[i]] > dist[node] + c[i])) {
                    dist[v[i]] = dist[node] + c[i];
                    if (!visited[v[i]]) {
                        visited[v[i]] = true; q.push(v[i]);
                    }
                }
            }
        }
        return dist[t] != -1;
    }

    long long dfs(int pos, long long flow) {
        if (pos == t) return flow;
        visited[pos] = true;
        long long remaining = flow;
        for (int &i = current[pos] != -1 ? current[pos] : head[pos]; i != -1; i = nxt[i]) {
            if (!visited[v[i]] && w[i] && dist[v[i]] == dist[pos] + c[i]) {
                current[pos] = i;
                long long pushed = dfs(v[i], min(flow, w[i]));
                cost += pushed * c[i];
                w[i] -= pushed; w[i ^ 1] += pushed;
                flow -= pushed;
                if (!flow) break;
            }
        }
        return remaining - flow;
    }

public:
    FlowNetwork() {
        memset(head, -1, sizeof(head));
        memset(nxt, -1, sizeof(nxt));
    }

    inline void addEdge(int u, int v, long long w, int c) {
        add_edge(u, v, w, c);
        add_edge(v, u, 0, -c);
    }

    long long minCostFlow(int s, int t) {
        cost = 0; this->t = t;
        while (spfa(s, t)) {
            memset(current, -1, sizeof(current));
            dfs(s, INF);
        }
        return cost;
    }
};

int main() {
    ios::sync_with_stdio(false);
    int n, m, kk, c, d; cin >> n >> m >> kk >> c >> d;
    int a[55]; for (int i = 1; i <= kk; i++) cin >> a[i];
    int s = 0, t = n * 100 + 1;
    FlowNetwork flow;
    for (int i = 1; i <= 100; i++) flow.addEdge(i, t, INF, 0);
    for (int i = 1; i <= kk; i++) flow.addEdge(s, (a[i] - 1) * 100 + 1, 1, 0);
    for (int i = 2; i <= n; i++)
        for (int j = 1; j < 100; j++)
            flow.addEdge((i - 1) * 100 + j, (i - 1) * 100 + j + 1, INF, c);
    int t1, t2;
    for (int _ = 1; _ <= m; _++) {
        cin >> t1 >> t2;
        for (int i = 1; i < 100; i++)
            for (int j = 1; j <= kk; j++) {
                int val = c + d * (j * j - (j - 1) * (j - 1));
                flow.addEdge((t1 - 1) * 100 + i, (t2 - 1) * 100 + i + 1, 1, val);
                flow.addEdge((t2 - 1) * 100 + i, (t1 - 1) * 100 + i + 1, 1, val);
            }
    }
    cout << flow.minCostFlow(s, t) << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
const int MAXN = 10000, MAXM = MAXN * 100;
const long long INF = LLONG_MAX >> 5;

struct Edge {
    int to; long long capacity; int cost; int rev;
};

class MinCostMaxFlow {
private:
    int n;
    std::vector<std::vector<Edge>> graph;
    std::vector<long long> dist;
    std::vector<int> parent;
    std::vector<int> parentEdge;
    long long totalCost;
public:
    MinCostMaxFlow(int n): n(n) {
        graph.resize(n);
        dist.resize(n);
        parent.resize(n);
        parentEdge.resize(n);
        totalCost = 0;
    }

    void addEdge(int u, int v, long long cap, int cst) {
        graph[u].push_back({v, cap, cst, (int)graph[v].size()});
        graph[v].push_back({u, 0, -cst, (int)graph[u].size() - 1});
    }

    long long minCostFlow(int s, int t) {
        long long flow = 0;
        while (true) {
            std::fill(dist.begin(), dist.end(), LLONG_MAX);
            dist[s] = 0;
            std::vector<bool> inQueue(n, false);
            std::queue<int> q; q.push(s);
            while (!q.empty()) {
                int u = q.front(); q.pop();
                inQueue[u] = false;
                for (int i = 0; i < (int)graph[u].size(); i++) {
                    Edge &e = graph[u][i];
                    if (e.capacity > 0 && dist[u] + e.cost < dist[e.to]) {
                        dist[e.to] = dist[u] + e.cost;
                        parent[e.to] = u;
                        parentEdge[e.to] = i;
                        if (!inQueue[e.to]) {
                            inQueue[e.to] = true;
                            q.push(e.to);
                        }
                    }
                }
            }
            if (dist[t] == LLONG_MAX) break;
            long long pushFlow = LLONG_MAX;
