	long long cost;
	long long rem() {
		return cap - flow;
	}
	edge(){}
	edge(int _u, int _v, long long _cap, long long _flow, long long _cost) {
		u = _u;
		v = _v;
		cap = _cap;
		flow = _flow;
		cost = _cost;
	}
};


int nodes; 
