                add_edge(g, u * 101 + j, v * 101 + j + 1, 1, cost_diff);
                add_edge(g, v * 101 + j, u * 101 + j + 1, 1, cost_diff);
            }
        }
    }
    int s = total_nodes - 2;
    int t = total_nodes - 1;
