int bfs(int s, int t){
    rep(i, 0, t+1)d[i] = inf, vis[i] = 0;
    queue<int>q;
    q.push(s); d[s] = 0;
    while(!q.empty()){
        int u = q.front(); q.pop(); vis[u] = 0;
        for(int i = head[u]; ~i; i = g[i].next){
            int j = g[i].v;
            if(g[i].c && d[j] > d[u] + g[i].w){
                d[j] = d[u] + g[i].w;
                p[j] = i;
                if(!vis[j]){
                    vis[j] = 1;
                    q.push(j);
                }
            }
        }
    }
    return d[t] < inf;
}
