using namespace __gnu_pbds;

typedef tree<ll, null_type, less<ll>, rb_tree_tag, tree_order_statistics_node_update> ordered_set;

template<typename F, typename C>
struct MinCostFlow {
    struct Edge {
        size_t src, dst, rev;
        F flow, cap;
        C cost;
    };
    int n;
    vector<vector<Edge>> adj;
    vector<C> potential;
    vector<F> dist;
    vector<Edge*> back;
    MinCostFlow(int n) : n(n), adj(n), potential(n), dist(n), back(n, nullptr) {}
    void add_edge(size_t s, size_t t, F cap, C cst) {
        adj[s].push_back({s, t, adj[t].size(), 0, cap, cst});
        adj[t].push_back({t, s, adj[s].size() - 1, 0, 0, -cst});
    }
    C rcost(const Edge &e) { return e.cost + potential[e.src] - potential[e.dst]; }
    const C INF = numeric_limits<C>::max();
    C dijkstra(int s, int t) {
        fill(dist.begin(), dist.end(), INF);
        priority_queue<pair<C, int>, vector<pair<C, int>>, greater<>> pq;
        dist[s] = 0;
        pq.push({0, s});
        while (!pq.empty()) {
            auto [d, u] = pq.top(); pq.pop();
            if (d > dist[u]) continue;
            if (u == t) break;
            for (auto &e : adj[u]) {
                if (e.flow < e.cap && dist[e.dst] > dist[u] + rcost(e)) {
                    back[e.dst] = &e;
                    dist[e.dst] = dist[u] + rcost(e);
                    pq.push({dist[e.dst], e.dst});
                }
            }
        }
        return dist[t];
    }
    pair<F, C> max_flow(int s, int t) {
        F total_flow = 0;
        C total_cost = 0;
        fill(potential.begin(), potential.end(), 0);
        fill(dist.begin(), dist.end(), 0);
        fill(back.begin(), back.end(), nullptr);
        while (dijkstra(s, t) < INF) {
            for (int u = 0; u < n; ++u)
                if (dist[u] < dist[t]) potential[u] += dist[u] - dist[t];
            F flow_cap = numeric_limits<F>::max();
            for (Edge *e = back[t]; e != nullptr; e = back[e->src]) {
                flow_cap = min(flow_cap, e->cap - e->flow);
            }
            for (Edge *e = back[t]; e != nullptr; e = back[e->src]) {
                e->flow += flow_cap;
                adj[e->dst][e->rev].flow -= flow_cap;
            }
            total_flow += flow_cap;
            total_cost += flow_cap * (potential[t] - potential[s]);
        }
        return {total_flow, total_cost};
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;
    MinCostFlow<int, int> g((n + 2) * 102);
    for (int i = 0; i < 102; ++i)
        g.add_edge((i * (n + 2)) + 1, i * (n + 2), 100, i * c);
    for (int i = 0; i < 101; ++i)
        for (int j = 0; j <= n; ++j)
            g.add_edge(j + (i * (n + 2)), j + ((i + 1) * (n + 2)), 100, 0);
    for (int i = 0; i < k; ++i) {
        int u; cin >> u;
        g.add_edge(n + 1, u, 1, 0);
    }
    for (int i = 0; i < m; ++i) {
        int u, v; cin >> u >> v;
        for (int j = 0; j < 101; ++j)
            for (int f = 0; f < k; ++f) {
                g.add_edge(u + (j * (n + 2)), v + ((j + 1) * (n + 2)), 1, ((2 * f) + 1) * d);
                g.add_edge(v + (j * (n + 2)), u + ((j + 1) * (n + 2)), 1, ((2 * f) + 1) * d);
            }
    }
    auto [flow, cost] = g.max_flow(n + 1, (101 * (n + 2)));
    print(cost);
    return 0;
}

