			if(e.c) pot[e.v] = min(pot[e.v], pot[u] + e.p); }
	ll mcf(int s, int t, ll& price, int n, bool sparse) {
		fill(vis, vis+n, 0); fill(dist, dist+n, INF); dist[s] = 0;
		if(sparse) {
			queue<int> q; q.push(s);
			while(!q.empty()) {
				int u = q.front(); q.pop(); if(vis[u]) continue;
				for(const Edge& e:adj[u]) {
					if (e.f < e.c && dist[e.v] > dist[u] + pot[u] - pot[e.v] + e.p) {
						dist[e.v] = dist[u] + pot[u] - pot[e.v] + e.p; par[e.v] = e.r;
						q.push(e.v);
					}
				}
			}
		} else {
			for(int u=s; u!=-1; ) {
				vis[u]=true;
				for(const Edge& e:adj[u]) {
					if(e.f<e.c && dist[e.v]>dist[u]+pot[u]-pot[e.v]+e.p) {
						dist[e.v]=dist[u]+pot[u]-pot[e.v]+e.p; par[e.v]=e.r;
					}
				}
				u=-1; ll best=INF;
				for(int i=0; i<n; i++) if(!vis[i] && dist[i]<best) { best=dist[i]; u=i; }
			}
		}
		if(dist[t]>=INF) return 0;
		ll df=INF;
		for(int u=t; u!=s; u=adj[par[u]][adj[par[u]][0].r].v) {
			const Edge& r=adj[u][par[u]];
			df=min(df, adj[r.v][r.r].c - adj[r.v][r.r].f);
		}
		for(int u=t; u!=s; u=adj[par[u]][adj[par[u]][0].r].v) {
			Edge& r=adj[u][par[u]], &e=adj[r.v][r.r];
			e.f+=df; r.f-=df; price+=df*e.p;
		}
		for(int i=0; i<n; i++) { pot[i]=min(INF, dist[i]+pot[i]); }
		return df;
	}
	ll min_cost_flow(int s, int t, ll& price, int n=N, bool sparse=false) {
		pot_init(n); ll flow=0; price=0;
		while(ll df=mcf(s,t,price,n,sparse)) { flow+=df; }
		return flow;
	}
}

