void pushFlow() {
  FOR(i, 0, N) {
    dist[i] = INF64;
    pred[i] = -1;
    pe[i] = -1;
    inq[i] = 0;
  }
  dist[source] = 0;
  queue<int> q;
  q.push(source);
  inq[source] = 1;
  while (!q.empty()) {
    int k = q.front(); q.pop();
    inq[k] = 0;
    for (auto x : g[k]) {
      if (!residualCapacity(x)) {
        continue;
      }
      int cost = e[x].cost;
      int y = e[x].y;
      if (dist[y] > dist[k] + cost) {
        dist[y] = dist[k] + cost;
        pred[y] = k;
        pe[y] = x;
        if (inq[y] == 0) {
          inq[y] = 1;
          q.push(y);
        }
      }
    }
