  int from;
  int to;
  int flow;
  int cost;

  Edge() {};

  Edge(int _from, int _to, int _flow, int _cost) 
    : from(_from), to(_to), flow(_flow), cost(_cost) {};
};

vector<Edge> edges;
const int MAXN = 1e6 + 7;
vector<int> adj[MAXN];

ll totalCost = 0;
ll dist[MAXN];
int parent[MAXN];
int parentEdge[MAXN];
int inQ[MAXN];

int s = MAXN - 2;
int t = MAXN - 1;

int residual(int eIdx) {
  return edges[eIdx].to - edges[eIdx].flow;
}

void shortestPath() {
  for (int i = 0; i < MAXN; i++) {
    dist[i] = INF64;
    parent[i] = -1;
    parentEdge[i] = -1;
    inQ[i] = 0;
  }
  dist[s] = 0;
  queue<int> q;
  q.push(s);
  inQ[s] = 1;
  while (!q.empty()) {
    int u = q.front(); q.pop();
    inQ[u] = 0;
    for (auto eIdx : adj[u]) {
      if (!residual(eIdx)) continue;
      int cst = edges[eIdx].cost;
      int v = edges[eIdx].from;
      if (dist[v] > dist[u] + cst) {
        dist[v] = dist[u] + cst;
        parent[v] = u;
        parentEdge[v] = eIdx;
        if (!inQ[v]) {
          inQ[v] = 1;
          q.push(v);
        }
      }
    }
  }
}

void findFlow() {
  shortestPath();
  int cur = t;
  while (cur != s) {
    edges[parentEdge[cur]].flow++;
    edges[parentEdge[cur] ^ 1].flow--;
    cur = parent[cur];
  }
  totalCost += dist[t];
}

void createEdge(int u, int v, int cap, int cst) {
  adj[u].push_back(edges.size());
  edges.emplace_back(u, v, 0, cst);
  adj[v].push_back(edges.size());
  edges.emplace_back(v, u, cap, -cst);
}

int n, m, k, c, d;
const int T = 101;

void buildGraph() {
  scanf("%d %d %d %d %d", &n, &m, &k, &c, &d);
  for (int i = 0; i < k; i++) {
    int x; scanf("%d", &x);
    --x;
    createEdge(s, x, 1, 0);
  }
  for (int i = 0; i < T; i++) {
    createEdge(i * n, t, k, i * c);
  }
  for (int i = 0; i < m; i++) {
    int x, y; scanf("%d %d", &x, &y);
    --x; --y;
    for (int t = 0; t < T - 1; t++) {
      for (int j = 0; j < k; j++) {
        createEdge(x + t * n, y + t * n + n, 1, d * (j * 2 + 1));
      }
    }
    for (int t = 0; t < T - 1; t++) {
      for (int j = 0; j < k; j++) {
        createEdge(y + t * n, x + t * n + n, 1, d * (j * 2 + 1));
      }
    }
  }
}

void solve() {
  for (int i = 0; i < n; i++) {
    for (int t = 0; t < T - 1; t++) {
      createEdge(i + t * n, i + t * n + n, k, 0);
    }
  }
  for (int i = 0; i < k; i++) {
    findFlow();
  }
  printf("%lld\n", totalCost);
}

int main() {
  buildGraph();
  solve();
  return 0;
}

