#include <bits/stdc++.h>
using namespace std;

struct Edge {
    int y, capacity, flow, cost;
    Edge() {}
    Edge(int y, int c, int f, int cost) : y(y), capacity(c), flow(f), cost(cost) {}
};

vector<Edge> network;
const int MAXN = 14043;
vector<int> adj[MAXN];

long long total_cost = 0;
long long dist[MAXN];
int parent_node[MAXN], parent_edge[MAXN], inq[MAXN];

const long long INF = 1e18;
int s = MAXN - 2;
int t = MAXN - 1;

int residual(int idx) {
    return network[idx].capacity - network[idx].flow;
}

void find_path() {
    for (int i = 0; i < MAXN; i++) {
        dist[i] = INF;
        parent_node[i] = -1;
        parent_edge[i] = -1;
        inq[i] = 0;
    }
    dist[s] = 0;
    queue<int> q;
    q.push(s);
    inq[s] = 1;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        inq[u] = 0;
        for (auto e_idx : adj[u]) {
            if (residual(e_idx) == 0) continue;
            int y = network[e_idx].y;
            int cst = network[e_idx].cost;
            if (dist[y] > dist[u] + cst) {
                dist[y] = dist[u] + cst;
                parent_node[y] = u;
                parent_edge[y] = e_idx;
                if (!inq[y]) {
                    inq[y] = 1;
                    q.push(y);
                }
            }
        }
    }
    int cur = t;
    while (cur != s) {
        network[parent_edge[cur]].flow++;
        network[parent_edge[cur] ^ 1].flow--;
        cur = parent_node[cur];
    }
    total_cost += dist[t];
}

void add_link(int from, int to, int cap, int cst) {
    adj[from].push_back(network.size());
    network.emplace_back(to, cap, 0, cst);
    adj[to].push_back(network.size());
    network.emplace_back(from, 0, 0, -cst);
}

