    for (int i = 0; i < T; i++)
        add_link(i * n, t, k, i * c);
    for (int i = 0; i < m; i++) {
        int x, y; cin >> x >> y; --x; --y;
        for (int i = 0; i < T - 1; i++) {
            for (int j = 0; j < k; j++) {
                add_link(x + i * n, y + i * n + n, 1, d * (j * 2 + 1));
            }
        }
        for (int i = 0; i < T - 1; i++) {
            for (int j = 0; j < k; j++) {
                add_link(y + i * n, x + i * n + n, 1, d * (j * 2 + 1));
            }
        }
    }
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < T - 1; j++) {
            add_link(i + j * n, i + j * n + n, k, 0);
        }
    }
    for (int i = 0; i < k; i++) {
        find_path();
    }
    cout << total_cost << endl;
}

