		A[x] = y;
	}

	void init() {
		_init(A, 1, N, 1);
	}

	ll query(int left, int right) {
		return _query(left, right, 1, 1, N);
	}

	ll update(int index, int newValue) {
		return _update(index, newValue, 1, 1, N);
	}
};
