class Dijkstra {
    int N;
    vector<vector<pair<int, int>>> E;
public:
    Dijkstra(int n) : N(n), E(n + 1) {}
    void insert(int u, int v, int w) { E[u].push_back({v, w}); }
    vector<int> dijkstra(int start, int end) {
        vector<int> dist(N + 1, INT_MAX);
        dist[start] = 0;
        priority_queue<pair<int, int>> pq;
        pq.push({0, start});
        while (!pq.empty()) {
            int w = -pq.top().first;
            int u = pq.top().second;
            pq.pop();
            if (u == end) return dist;
            if (dist[u] < w) continue;
            for (auto &edge : E[u]) {
                int v = edge.first, w2 = w + edge.second;
                if (dist[v] > w2) {
                    dist[v] = w2;
                    pq.push({-w2, v});
                }
            }
        }
        return dist;
    }
    void run() {
        int n, e, s, u, v, w;
        scanf("%d%d", &n, &e);
        Dijkstra dk(n);
        scanf("%d", &s);
        for (int i = 0; i < e; i++) {
            scanf("%d%d%d", &u, &v, &w);
            dk.insert(u, v, w);
        }
        vector<int> ans = dk.dijkstra(s, N);
        for (int i = 1; i <= n; i++) {
            if (ans[i] >= INT_MAX) printf("INF\n");
            else printf("%d\n", ans[i]);
        }
    }
};

class Prim {
    int N;
    vector<vector<pair<int, int>>> E;
public:
    Prim(int n) : N(n), E(n + 1) {}
    void insert(int u, int v, int w) { E[u].push_back({v, w}); }
    void execute(long long &cost) {
        vector<int> dist(N + 1, INT_MAX);
        vector<bool> selected(N + 1, false);
        dist[1] = 0;
        priority_queue<pair<int, int>> pq;
        pq.push({0, 1});
        cost = 0;
        for (int k = 0; k < N; k++) {
            int w = -pq.top().first;
            int u = pq.top().second;
            pq.pop();
            if (selected[u]) { k--; continue; }
            cost += w; selected[u] = true;
            for (auto &edge : E[u]) {
                int v = edge.first, w2 = edge.second;
                if (!selected[v] && dist[v] > w2) {
                    dist[v] = w2;
                    pq.push({-w2, v});
                }
            }
        }
    }
    void run() {
        int n, e, s, u, v, w;
        scanf("%d%d", &n, &e);
        Prim pm(n);
        scanf("%d", &s);
        for (int i = 0; i < e; i++) {
            scanf("%d%d%d", &u, &v, &w);
            pm.insert(u, v, w);
        }
        long long cost = 0;
        pm.execute(cost);
        printf("%lld", cost);
    }
};

class Floyd {
