        for (int i = 0; i < N; i++) {
            int u = -1, minDist = INT_MAX;
            while (!pq.empty()) {
                u = pq.top().second;
                pq.pop();
                if (!inMST[u]) break;
            }
            if (u == -1 || inMST[u]) break;
            inMST[u] = true;
            totalCost += dist[u];
            for (auto &edge : E[u]) {
                int v = edge.first, w = edge.second;
                if (!inMST[v] && dist[v] > w) {
                    dist[v] = w;
                    pq.push({-w, v});
                }
            }
        }
