#include <iostream>
#include <vector>
#include <iomanip>
using namespace std;

int main() {
    int total, target;
    cin >> total >> target;
    vector<double> probabilities(total);
    for (int i = 0; i < total; ++i) cin >> probabilities[i];

    int positive_count = 0;
    for (auto p : probabilities) if (p > 1e-6) ++positive_count;

    if (positive_count <= target) {
        for (auto p : probabilities) {
            cout << (p > 1e-6 ? "1 " : "0 ");
        }
        cout << "\n";
        return 0;
    }

    vector<double> result(total, 0.0);
    vector<double> dynamic_prog(1 << total, 0.0);
    dynamic_prog[0] = 1.0;

    for (int mask = 0; mask < (1 << total); ++mask) {
        double sum_probs = 0.0;
        for (int i = 0; i < total; ++i)
            if (mask & (1 << i))
                sum_probs += probabilities[i];
        if (sum_probs >= 0.99999) continue;
        for (int i = 0; i < total; ++i) {
            if (mask & (1 << i)) continue;
            dynamic_prog[mask | (1 << i)] += dynamic_prog[mask] * probabilities[i] / (1 - sum_probs);
        }
    }

    for (int mask = 0; mask < (1 << total); ++mask) {
        int count_bits = 0;
        for (int i = 0; i < total; ++i)
            if (mask & (1 << i))
                ++count_bits;
        if (count_bits != target) continue;
        for (int i = 0; i < total; ++i)
            if (mask & (1 << i))
                result[i] += dynamic_prog[mask];
    }

    cout << fixed << setprecision(13);
    for (auto v : result) cout << v << " ";
    cout << "\n";
    return 0;
}

