using namespace std;

int main() {
    int n, k;
    cin >> n >> k;
    vector<double> p(n);
    for (int i = 0; i < n; ++i) cin >> p[i];

    int count_nonzero = 0;
    for (auto &prob : p) if (prob > 1e-6) ++count_nonzero;

    if (count_nonzero <= k) {
        for (auto &prob : p) {
            cout << (prob > 1e-6 ? "1 " : "0 ");
        }
        cout << "\n";
        return 0;
    }

    vector<double> ans(n, 0.0);
    vector<double> dp(1 << n, 0.0);
    dp[0] = 1.0;

    for (int mask = 0; mask < (1 << n); ++mask) {
        double sum_p = 0.0;
        for (int i = 0; i < n; ++i)
            if (mask & (1 << i))
                sum_p += p[i];
        if (sum_p >= 0.99999) continue;
        for (int i = 0; i < n; ++i) {
            if (mask & (1 << i)) continue;
            dp[mask | (1 << i)] += dp[mask] * p[i] / (1 - sum_p);
        }
    }

    for (int mask = 0; mask < (1 << n); ++mask) {
        int bits_count = __builtin_popcount(mask);
        if (bits_count != k) continue;
        for (int i = 0; i < n; ++i)
            if (mask & (1 << i))
                ans[i] += dp[mask];
    }

    cout << fixed << setprecision(13);
    for (auto v : ans) cout << v << " ";
    cout << "\n";

    return 0;
}

