using namespace std;

int main() {
    int total_numbers, max_k;
    cin >> total_numbers >> max_k;
    vector<double> probabilities(total_numbers);
    vector<int> index_map(total_numbers, -1);
    int valid_count = 0;

    for (int i = 0; i < total_numbers; ++i) {
        cin >> probabilities[i];
        if (probabilities[i] > 1e-9) {
            index_map[i] = valid_count++;
        }
    }

    max_k = min(max_k, valid_count);

    vector<double> D(1 << valid_count, 0.0);
    vector<double> sum_prob(1 << valid_count, 0.0);
    vector<double> Q(valid_count, 0.0);

    D[0] = 1.0;

    for (int mask = 1; mask < (1 << valid_count); ++mask) {
        int last_bit = __builtin_ctz(mask);
        int prev_mask = mask ^ (1 << last_bit);
        sum_prob[mask] = sum_prob[prev_mask] + probabilities[last_bit];
        for (int i = 0; i < valid_count; ++i) {
            if ((mask >> i) & 1) continue;
            D[mask | (1 << i)] += D[mask] * probabilities[i] / (1.0 - sum_prob[mask]);
        }
    }

    for (int mask = 0; mask < (1 << valid_count); ++mask) {
        int count_bits = __builtin_popcount(mask);
        if (count_bits == max_k) {
            for (int i = 0; i < valid_count; ++i) {
                if ((mask >> i) & 1) {
                    Q[i] += D[mask];
                }
            }
        }
