using namespace std;

void perform();

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int test_cases = 1;
    for (int i = 0; i < test_cases; ++i) {
        perform();
    }
    return 0;
}

void perform() {
    int total, limit;
    cin >> total >> limit;
    vector<double> probabilities(total);
    for (int i = 0; i < total; ++i) {
        cin >> probabilities[i];
    }
    for (int i = 0; i < total; ++i) {
        if (fabs(probabilities[i]) < 1e-6) {
            cout << "0 ";
            continue;
        }
        int subset_len = total - 1;
        vector<double> dp(1 << subset_len, 0.0);
        vector<double> subset_probs;
        for (int j = 0; j < total; ++j) {
            if (j != i) {
                subset_probs.push_back(probabilities[j]);
            }
        }
        dp[0] = probabilities[i];
        double total_sum = dp[0];
        for (int mask = 1; mask < (1 << subset_len); ++mask) {
            double sumP = 0.0, sumVal = 0.0;
            int count = 0;
            for (int t = 0; t < subset_len; ++t) {
                if (mask & (1 << t)) {
                    sumP += subset_probs[t];
                    sumVal += subset_probs[t] * dp[mask ^ (1 << t)];
                    ++count;
                }
            }
            dp[mask] = sumVal / (1 - sumP);
            if (count < limit) {
                total_sum += dp[mask];
            }
        }
        cout << total_sum << " ";
    }
}

