            cout << "0 ";
            continue;
        }
        int m = n - 1;
        vector<double> dp(1 << m, 0.0);
        vector<double> others;
        for (int j = 0; j < n; ++j) {
            if (j != i) {
                others.push_back(probs[j]);
            }
