    REP(i, 1, P)
    {
        Parent[i] = i;
        Rank[i] = 1;
    }

    REP(i, 1, P)
    {
        int value = ((LL)K * (LL)i) % P;
        int Pa = find_parent(i);
        int Pb = find_parent(value);

        if(Pa != Pb)
            Union(Pa, Pb);
    }

    REP(i, 1, P)
        groups.insert(find_parent(i));

    if(!K)
        ways = fast_exp_pow((LL)P, (LL)(P-1), (LL)MAXN);
    else if(K == 1)
        ways = fast_exp_pow((LL)P, (LL)P, (LL)MAXN);
