#include <iostream>
using namespace std;
const int MOD = 1000000007;
int power(int a,int b)
{
    long long ans=1;
    while(b)
    {
        ans*=a;
        ans%=MOD;
        --b;
    }
    return ans;
}
int main()
{
	int p,k;
	cin>>p>>k;
	if(k==0)
		cout<<power(p,p-1);
	else if(k==1)
		cout<<power(p,p);
	else
	{
		int ord = 1, cur = k;
		while(cur!=1)
		{
			cur = (long long) cur * k % p;
			ord += 1;
		}     		
		cout<<power(p,(p-1)/ord);
	}
	return 0;
}

#include <iostream>
using namespace std;
const int MOD = 1000000007;

int mod_pow(int base, int exp) {
    long long result = 1;
    for (int i = 0; i < exp; ++i) {
        result = (result * base) % MOD;
    }
    return (int)result;
}

int main() {
    int p, k;
    cin >> p >> k;
    if (k == 0) {
        cout << mod_pow(p, p - 1);
    } else if (k == 1) {
        cout << mod_pow(p, p);
    } else {
        int order = 1, current = k;
        while (current != 1) {
            current = (long long)current * k % p;
            order++;
        }
        cout << mod_pow(p, (p - 1) / order);
    }
    return 0;
}

#include <iostream>
using namespace std;
const int MOD = 1000000007;

int compute_power(int base, int exponent) {
    long long result = 1;
    while (exponent > 0) {
        result = (result * base) % MOD;
        --exponent;
    }
    return (int)result;
}

int main() {
    int p, k;
    cin >> p >> k;
    if (k == 0) {
        cout << compute_power(p, p - 1);
    } else if (k == 1) {
        cout << compute_power(p, p);
    } else {
        int order = 1, val = k;
        while (val != 1) {
            val = (long long)val * k % p;
            order++;
        }
        cout << compute_power(p, (p - 1) / order);
    }
    return 0;
}

