#include <bits/stdc++.h>
using namespace std;

long long modExp(long long base, long long exp, long long mod) {
    long long result = 1;
    long long current = base % mod;
    while (exp > 0) {
        if (exp & 1) result = (result * current) % mod;
        current = (current * current) % mod;
        exp >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n, m;
    cin >> n >> m;
    if (m == 0) {
        cout << modExp(n, n - 1, 1000000007) << "\n";
    } else if (m == 1) {
        cout << modExp(n, n, 1000000007) << "\n";
    } else {
        vector<long long> parent(n + 1);
        for (long long i = 0; i <= n; ++i) parent[i] = i;
        vector<long long> rank(n + 1, 0);

        function<long long(long long)> find_root = [&](long long x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        };

        auto merge = [&](long long a, long long b) {
            long long pa = find_root(a);
            long long pb = find_root(b);
            if (pa != pb) {
                if (rank[pa] >= rank[pb]) {
                    parent[pb] = pa;
                    if (rank[pa] == rank[pb]) rank[pa]++;
                } else {
                    parent[pa] = pb;
                }
            }
        };

        for (long long i = 1; i < n; ++i) {
            long long b = (i * m) % n;
            merge(i, b);
        }

        set<long long> groups;
        for (long long i = 1; i < n; ++i) {
            groups.insert(find_root(i));
        }
        long long total_groups = (long long)groups.size();
        cout << modExp(n, total_groups, 1000000007) << "\n";
    }
    return 0;
}

