int maxFlow(int n, int s, int t) {
    int totalFlow = 0;
    while (true) {
        memset(pre, -1, sizeof(pre));
        dist[s] = INF;
        int front = 0, rear = 0;
        que[rear++] = s;
        while (front < rear && pre[t] < 0) {
            int u = que[front++];
            for (int v = 0; v < n; v++) {
                if (pre[v] < 0 && cap[u][v] - flow[u][v] > 0) {
                    pre[v] = u;
                    dist[v] = min(dist[u], cap[u][v] - flow[u][v]);
                    que[rear++] = v;
                }
            }
        }
        if (pre[t] < 0) break;
        for (int v = t; v != s; v = pre[v]) {
            flow[pre[v]][v] += dist[t];
            flow[v][pre[v]] -= dist[t];
        }
        totalFlow += dist[t];
    }
    return totalFlow;
}

