#define ll long long
ll INF = numeric_limits<ll>::max();

class max_flow {
    static const ll INF = numeric_limits<ll>::max();

    struct edge {
        int t;
        unsigned long rev;
        ll cap, f;
    };

    vector<edge> adj[MAX_N];
    int dist[MAX_N];
    int ptr[MAX_N];

    bool bfs(int s, int t) {
        fill(dist, dist + MAX_N, -1);
        dist[s] = 0;
        queue<int> q({s});
        while (!q.empty() && dist[t] == -1) {
            int n = q.front();
            q.pop();
            for (auto& e : adj[n]) {
                if (dist[e.t] == -1 && e.cap != e.f) {
                    dist[e.t] = dist[n] + 1;
                    q.push(e.t);
                }
            }
        }
        return dist[t] != -1;
    }

    ll augment(int n, ll amt, int t) {
        if (n == t) return amt;
        for (; ptr[n] < (int)adj[n].size(); ++ptr[n]) {
            auto& e = adj[n][ptr[n]];
            if (dist[e.t] == dist[n] + 1 && e.cap != e.f) {
                ll flow = augment(e.t, min(amt, e.cap - e.f), t);
                if (flow != 0) {
                    e.f += flow;
                    adj[e.t][e.rev].f -= flow;
                    return flow;
                }
            }
        }
        return 0;
    }

public:
    void add(int u, int v, ll cap=1, ll rcap=0) {
        adj[u].push_back({v, adj[v].size(), cap, 0});
        adj[v].push_back({u, adj[u].size() - 1, rcap, 0});
    }

    ll calc(int s, int t) {
        ll flow = 0;
        while (bfs(s, t)) {
            fill(ptr, ptr + MAX_N, 0);
            while (ll df = augment(s, INF, t))
                flow += df;
        }
        return flow;
    }

    void clear() {
        for (int n = 0; n < MAX_N; ++n) adj[n].clear();
    }
};

