	{
		scanf("%s",inp[i]);
	}
	for (int i = 0; i < n; ++i)
	{
		for (int j = 0; j < n; ++j)
		{
			if(inp[i][j]=='Y' || inp[i][j]=='Z')
			{
				plant[i][j][0]=inp[i][j]-'X';
				source_cap[i][j]=0;
			}
			else
			{
				plant[i][j][0]=0;
				source_cap[i][j]=inp[i][j]-'0';
			}
		}
	}
	for (int i = 0; i < n; ++i)
	{
		scanf("%s",inp[i]);
	}
	for (int i = 0; i < n; ++i)
	{
		for (int j = 0; j < n; ++j)
		{
			if(inp[i][j]=='Y' || inp[i][j]=='Z')
			{
				plant[i][j][0]=inp[i][j]-'X';
				sink_cap[i][j]=0;
			}
			else
			{
				plant[i][j][0]=0;
				sink_cap[i][j]=inp[i][j]-'0';
			}
		}
	}
	for (int curr_time = 1; curr_time <= t; ++curr_time)
	{
		for (int i = 0; i < n; ++i)
		{
			for (int j = 0; j < n; ++j)
			{
				plant[i][j][curr_time]=plant[i][j][curr_time-1];
			}
		}
		for (int i = 0; i < n; ++i)
		{
			for (int j = 0; j < n; ++j)
			{
				if(plant[i][j][curr_time-1]==2)
				{
					for (int k = 0; k < 4; ++k)
					{
						if(is_valid(i+dr[k],j+dc[k]))
						{
							if(plant[i+dr[k]][j+dc[k]][curr_time-1]==0)
								plant[i+dr[k]][j+dc[k]][curr_time]=2;
						}
					}
				}
			}
		}
	}
	counter=1;
	for (int i = 0; i < n; ++i)
	{
		for (int j = 0; j < n; ++j)
		{
			if(source_cap[i][j]!=0)
			{
				source_num[i][j]=counter;
				counter++;
			}
			else
				source_num[i][j]=-1;
