        for (size_t i = 0; i + 1 < path.size(); ++i)
            for (size_t j = 0; j < G[path[i]].size(); ++j)
                if (G[path[i]][j].a == path[i + 1])
                    G[path[i]][j].res -= flow;
        for (size_t i = 1; i < path.size(); ++i)
            for (size_t j = 0; j < G[path[i]].size(); ++j)
                if (G[path[i]][j].a == path[i - 1])
                    G[path[i]][j].res += flow;
    }
    cout << odp;
    return 0;
