                graph[(int)points.size() + 1 + j].push_back({i + 1, 0});
            }
        }
    }
    int max_flow = 0;
    while (true)
    {
        vector<bool> visited(total_nodes, false);
        queue<int> q;
        visited[0] = true;
        q.push(0);
        vector<int> parent(total_nodes, -1);
        while (!q.empty())
        {
            int u = q.front();
            q.pop();
            for (auto &e : graph[u])
            {
                if (!visited[e.node] && e.capacity > 0)
                {
                    visited[e.node] = true;
                    parent[e.node] = u;
                    q.push(e.node);
                }
            }
        }
        if (parent[total_nodes - 1] == -1)
            break;
        vector<int> path;
        for (int v = total_nodes - 1; v != -1; v = parent[v])
            path.push_back(v);
        reverse(path.begin(), path.end());
        int min_cap = 1000;
        for (size_t i = 0; i + 1 < path.size(); ++i)
        {
            int u = path[i], v = path[i + 1];
            for (auto &e : graph[u])
                if (e.node == v)
                {
                    min_cap = min(min_cap, e.capacity);
                    break;
                }
        }
        max_flow += min_cap;
        for (size_t i = 0; i + 1 < path.size(); ++i)
        {
            int u = path[i], v = path[i + 1];
            for (auto &e : graph[u])
                if (e.node == v)
                {
                    e.capacity -= min_cap;
                    break;
                }
            for (auto &e : graph[v])
                if (e.node == u)
                {
                    e.capacity += min_cap;
                    break;
                }
        }
    }
    cout << max_flow;
    return 0;
}

