using namespace std;

const int MAXN = 2002;
const int INF = 1e9;

int capacity[MAXN][MAXN];
vector<int> adj[MAXN];
bool visited[MAXN];
int parent[MAXN];

int directions[][2] = { {1,0}, {0,1}, {-1,0}, {0,-1} };

int findFlow(int u) {
    if (u == 1) return INF;
    visited[u] = true;
    for (int v : adj[u]) {
        if (!visited[v] && capacity[u][v] > 0) {
            int flow = findFlow(v);
            if (flow > 0) {
                parent[v] = u;
                return min(flow, capacity[u][v]);
            }
        }
    }
    return 0;
}

int computeFlow() {
    int totalFlow = 0;
    while (true) {
        memset(visited, false, sizeof(visited));
        int flow = findFlow(0);
        if (flow == 0) break;
        totalFlow += flow;
        int v = 1;
        while (v != 0) {
            int u = parent[v];
            capacity[u][v] -= flow;
            capacity[v][u] += flow;
            v = u;
        }
    }
    return totalFlow;
}

int main() {
    ios::sync_with_stdio(false);
    int size, timeLimit;
    cin >> size >> timeLimit;

    for (int i = 0; i < 2 * size * size + 2; ++i) {
        adj[i].clear();
        for (int j = 0; j < 2 * size * size + 2; ++j)
            capacity[i][j] = 0;
    }

    vector<string> sci(size), capLab(size);
    int vert[50][50][2];
    int malfunctionIdx;

    int N = 2;
    for (int i = 0; i < size; ++i) {
        cin >> sci[i];
        for (int j = 0; j < size; ++j) {
            if (sci[i][j] >= '1' && sci[i][j] <= '9') {
                capacity[0][N] = sci[i][j] - '0';
                adj[0].push_back(N);
                adj[N].push_back(0);
                vert[i][j][0] = N++;
            } else if (sci[i][j] == 'Z') {
                malfunctionIdx = 100 * i + j;
                sci[i][j] = 'Y';
            }
        }
    }

    int M = N;
    for (int i = 0; i < size; ++i) {
        cin >> capLab[i];
        for (int j = 0; j < size; ++j) {
            if (capLab[i][j] >= '1' && capLab[i][j] <= '9') {
                capacity[M][1] = capLab[i][j] - '0';
                adj[M].push_back(1);
                vert[i][j][1] = M++;
            }
        }
    }

    int die[50][50];
    for (int i = 0; i < size; ++i)
        for (int j = 0; j < size; ++j)
            die[i][j] = timeLimit + 1;
    die[malfunctionIdx / 100][malfunctionIdx % 100] = 0;

    queue<int> q;
    q.push(malfunctionIdx);
    while (!q.empty()) {
        int x = q.front(); q.pop();
        int y = x % 100; x /= 100;
        for (auto d : directions) {
            int nx = x + d[0], ny = y + d[1];
            if (nx >= 0 && nx < size && ny >= 0 && ny < size && sci[nx][ny] != 'Y' && die[nx][ny] > die[x][y] + 1) {
                die[nx][ny] = die[x][y] + 1;
                q.push(100 * nx + ny);
            }
        }
    }

    int reach[50][50];
    for (int i = 0; i < size; ++i)
        for (int j = 0; j < size; ++j)
            reach[i][j] = timeLimit + 1;

    for (int i = 0; i < size; ++i) {
        for (int j = 0; j < size; ++j) {
            if (sci[i][j] >= '1' && sci[i][j] <= '9') {
                for (int x = 0; x < size; ++x)
