class HungarianSolver {
public:
    static const int MAXN = 2000;
    int matchCount, matchPos[MAXN], matchRev[MAXN];
    int solve(int n, vector<int> adj[]) {
        matchCount = 0;
        memset(matchPos, -1, sizeof(matchPos));
        memset(matchRev, -1, sizeof(matchRev));
        for (int i = 0; i < n; i++) {
            memset(used, 0, sizeof(used));
            if (tryMatch(i, adj)) matchCount++;
        }
        return matchCount;
    }
private:
    int used[MAXN];
    bool tryMatch(int u, vector<int> adj[]) {
        for (int v : adj[u]) {
            if (!used[v]) {
                used[v] = 1;
                if (matchRev[v] < 0 || tryMatch(matchRev[v], adj)) {
                    matchPos[u] = v;
                    matchRev[v] = u;
                    return true;
                }
            }
        }
        return false;
    }
};

