        vector<int> e[MAXN];
        Edge edge[MAXM * 2];

        void initialize(int n, int s, int t) {
                this->n = n;
                this->m = 0;
                this->source = s;
                this->sink = t;
                for (int i = 0; i < n; ++i) e[i].clear();
        }

        void connect(int a, int b, int c) {
                edge[m].v = b; edge[m].c = c;
                e[a].push_back(m);
                edge[m + 1].v = a; edge[m + 1].c = 0;
                e[b].push_back(m + 1);
                m += 2;
        }

        int capacity[MAXN], dist[MAXN], current[MAXN], parent[MAXN], path_length;
        void bfs() {
                queue<int> q;
                fill(capacity, capacity + n, 0);
                fill(dist, dist + n, n);
                dist[sink] = 0;
                q.push(sink);
                while (!q.empty()) {
                        int u = q.front(); q.pop();
                        for (auto id : e[u]) {
                                int v = edge[id].v;
                                if (dist[v] == n && edge[RE(id)].c > 0) {
                                        dist[v] = dist[u] + 1;
                                        q.push(v);
                                }
                        }
                }
        }

        void retreat(int v) {
                --capacity[dist[v]];
                dist[v] = n;
                for (size_t i = 0; i < e[v].size(); ++i) {
                        auto &arc = edge[e[v][i]];
                        if (dist[v] > dist[arc.v] + 1 && arc.c > 0) {
                                dist[v] = dist[arc.v] + 1;
                                parent[v] = i;
                        }
                }
                ++capacity[dist[v]];
        }

        int augment() {
                int flow = INT_MAX;
                int idx = -1;
                for (int i = 0; i < path_length; ++i) {
                        auto &arc = edge[e[parent[path[i]]][current[path[i]]]];
                        if (arc.c < flow) {
                                flow = arc.c;
                                idx = i;
                        }
                }
                for (int i = 0; i < path_length; ++i) {
                        int id = e[parent[path[i]]][current[path[i]]];
                        edge[id].c -= flow;
                        edge[RE(id)].c += flow;
                }
                path_length = idx;
                return flow;
        }

        int maxFlow() {
                int total = 0;
                bfs();
                fill(current, current + n, 0);
                path_length = 0;
                parent[source] = -1;
                int u = source;
                while (dist[source] != n) {
                        if (u == sink) {
