                                        parent[arc.v] = e[u][current[u]];
                                        u = arc.v;
                                        path_length++;
                                        advanced = true;
                                        break;
                                }
                        }
                        if (!advanced) {
                                if (capacity[dist[u]] == 1) break;
                                retreat(u);
                                if (u != source) {
                                        --path_length;
                                        u = edge[parent[u]].v;
                                }
                        }
                }
                return total;
        }
} fn;

