void pre(){
	memset(dist, 0x3f, sizeof(dist));
	memset(vis, 0, sizeof(vis));
	dist[rx][ry] = 0;
	vis[rx][ry] = 1;
	queue<int> qx, qy;
	qx.push(rx);
	qy.push(ry);
	while(!qx.empty()){
		int x = qx.front(); qx.pop();
		int y = qy.front(); qy.pop();
		for(int k = 0; k < 4; k++){
			int nx = x + dx[k];
			int ny = y + dy[k];
			if(good(nx, ny) && !vis[nx][ny]){
				dist[nx][ny] = dist[x][y] + 1;
				vis[nx][ny] = 1;
				qx.push(nx);
				qy.push(ny);
			}
		}
	}
}

