#define infinity 1e9+9
#define pii pair<int,int>
#define ppi pair<pii,int>
#define ll long long 














struct Edge
{
int u,v,flow,capacity;
Edge(int u,int v,int flow,int capacity)
{
this->u=u;
this->v=v;
this->flow=flow;
this->capacity=capacity;
}
};




int source,sink;
vector<vector<int> > G;
vector<Edge> e;

void addEdge(int u,int v,int capacity)
{
G[u].push_back(e.size());
e.push_back(Edge(u,v,0,capacity));
G[v].push_back(e.size());
e.push_back(Edge(v,u,0,0));
}



int ptr[1001];
int dist[1001];


bool findPath()
{
memset(dist,-1,sizeof dist);
dist[source]=0;
queue<int> Q;
Q.push(source);
while(!Q.empty())
{

    int u=Q.front();
    Q.pop();

    for(int i=0;i<G[u].size();++i)
    {
    int id=G[u][i];
    int v=e[id].v;

    if(dist[v]==-1 && e[id].flow<e[id].capacity)
        {
        dist[v]=dist[u]+1;
        Q.push(v);
        if(v==sink)
        return true;
        }
    }

}
return false;
}

ll sendFlow(int u,int flow)
{
if(flow==0)
return 0;

if(u==sink)
return flow;



for(;ptr[u]<G[u].size();++ptr[u])
{
int id=G[u][ptr[u]];
int v=e[id].v;
if(dist[v]!=dist[u]+1)
    continue;
ll pushed=sendFlow(v,min(flow,e[id].capacity-e[id].flow));
if(pushed)
{
    e[id].flow+=pushed;
    e[id^1].flow-=pushed;
    return pushed;  
}
}

return 0;

}







ll dinics()
{
ll flow=0;
while(findPath())
{   
    memset(ptr,0,sizeof ptr);
    while(int pushed=sendFlow(source,infinity))
        flow+=pushed;
}
return flow;
}










