const int move_dir[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};
int start, end_node, edge_count=1, size, max_time, INF, head[1000], queue_buffer[1000000], edges[1000000][3], depth[20][20], distance[20][20], point[20][20], supply[20][20];
char gridA[20][20], gridB[20][20];

void addEdge(int x, int y, int capacity) {
    edges[++edge_count][0]=y; edges[edge_count][1]=capacity; edges[edge_count][2]=head[x]; head[x]=edge_count;
    edges[++edge_count][0]=x; edges[edge_count][1]=0; edges[edge_count][2]=head[y]; head[y]=edge_count;
}

void perform_bfs(int x0, int y0, bool check) {
    int left=1, right=1, id=point[x0][y0];
    queue_buffer[left]=x0*1000 + y0;
    memset(distance, 63, sizeof(distance));
    INF=distance[0][0];
    distance[x0][y0]=0;
    while (left<=right) {
        int x=queue_buffer[left]/1000, y=queue_buffer[left]%1000; left++;
        if (check && supply[x][y]!=0 && distance[x][y]<=max_time && distance[x][y]<=depth[x][y])
            addEdge(id, supply[x][y], INF);
        if (distance[x][y]>max_time || distance[x][y]>=depth[x][y]) continue;
        if (id==3 && supply[x][y]==9) printf("%d\n", distance[x][y]);
        for (int i=0; i<4; i++) {
            int nx=x+move_dir[i][0], ny=y+move_dir[i][1];
            if (nx>0 && nx<=size && ny>0 && ny<=size && isdigit(gridA[nx][ny]) && distance[nx][ny]==INF) {
                distance[nx][ny]=distance[x][y]+1;
                queue_buffer[++right]=nx*1000+ny;
            }
        }
    }
}

int dist_arr[1000];

bool construct_path() {
    memset(dist_arr, 0, sizeof(dist_arr));
    int l=1, r=1; queue_buffer[l]=start; dist_arr[start]=1;
    while (l<=r) {
        int x=queue_buffer[l++]; 
        for (int i=head[x]; i; i=edges[i][2]) {
            int y=edges[i][0];
            if (dist_arr[y] || !edges[i][1]) continue;
            dist_arr[y]=dist_arr[x]+1; queue_buffer[++r]=y;
            if (y==end_node) return true;
        }
    }
    return false;
}

int flow_dfs(int x, int flow) {
    if (x==end_node) return flow;
    int remaining=flow;
    for (int i=head[x]; i; i=edges[i][2]) {
        int y=edges[i][0];
        if (dist_arr[y]!=dist_arr[x]+1 || !edges[i][1]) continue;
        int pushed=flow_dfs(y, min(remaining, edges[i][1]));
        remaining-=pushed; edges[i][1]-=pushed; edges[i^1][1]+=pushed;
        if (remaining==0) return flow;
    }
    if (remaining==flow) dist_arr[x]=-1;
    return flow - remaining;
}

