void bfs(int d[N][N], int sx, int sy)
{
    bool c[N][N] = {};
    for (int i = 0; i < n; ++i)
    {
        for (int j = 0; j < n; ++j)
        {
            d[i][j] = INF;
        }
    }
    queue<ban> q;
    c[sx][sy] = true;
    d[sx][sy] = 0;
    q.push(ban(sx, sy));
    while (!q.empty())
    {
        ban t = q.front();
        q.pop();
        for (int i = 0; i < 4; ++i)
        {
            ban h = t;
            h.x += xx[i];
            h.y += yy[i];
            if (h.x >= 0 && h.x < n && h.y >= 0 && h.y < n && !c[h.x][h.y] && '0' <= a[h.x][h.y] && a[h.x][h.y] <= '9')
            {
                c[h.x][h.y] = true;
                d[h.x][h.y] = d[t.x][t.y] + 1;
                q.push(h);
            }
        }
    }
}

bool dp[N * 6][N][N][N][N];
bool u[N][N][N][N];

int g[2 * N * N][2 * N * N];

