int  isok(int r,int c){
	if(r>0&&r<=n&&c>0&&c<=n&&ma[r][c]!=-1){
		return (r-1)*n+c;
	}
	return -1;
}

void BG(){
	N=n*n;
	memset(mat,-1,sizeof(mat));
	for(int r1=1;r1<=n;r1++){
		for(int c1=1;c1<=n;c1++){
			if(ma[r1][c1]==-1)continue;
			int p1=(r1-1)*n+c1;
			mat[p1][p1]=0;
			for(int i=0;i<4;i++){
				int r2=r1+stran[i][0];
				int c2=c1+stran[i][1];
				if(r2>0&&r2<=n&&c2>0&&c2<=n&&ma[r2][c2]!=-1){
					int p2=(r2-1)*n+c2;	
					mat[p1][p2]=1;
				}
			}	
		}
	}
}
int dis[maxn];
int qu[maxm];
int inq[maxn];
void spfa(){
	int fr=0;
	int re=1;
	for(int i=1;i<=N;i++)dis[i]=inf;
	int dd=(zr-1)*n+zc;
	dis[dd]=0;
	qu[0]=dd;
	while(fr<re){
		int now=qu[fr++];
		for(int i=1;i<=N;i++){
			if(mat[now][i]==1&&dis[i]>dis[now]+1){
				dis[i]=dis[now]+1;
				qu[re++]=i;
			}
		}
	}
}
void Floyd(){
	for(int i=1;i<=N;i++){
		for(int j=1;j<=N;j++){
			for(int z=1;z<=N;z++){
				if(mat[j][i]!=-1&&mat[i][z]!=-1){
					if(mat[j][z]==-1||mat[j][z]>mat[j][i]+mat[i][z]){
						mat[j][z]=mat[j][i]+mat[i][z];
					}
				}
			}
		}
	}
}
