int vis[12][12];
int dx[4] = {1, 0, -1, 0};
int dy[4] = {0, -1, 0, 1};
inline int X(int i, int j) { return i * n + j; }
inline int Y(int i, int j) { return n * n + i * n + j; }
inline int S() { return n * n * 2; }
inline int T() { return S() + 1; }
inline int N() { return T() + 1; }
struct Coord {
	int x, y, time, type;
	Coord() {}
	Coord(int x, int y, int time, int type): x(x), y(y), time(time), type(type) {}
};
void bfs(int startX, int startY) {
	queue<Coord> q;
	q.push(Coord(startX, startY, 0, 0));
	vis[startX][startY] = 1;
	q.push(Coord(zx, zy, 0, 1));
	while(!q.empty()) {
		Coord u = q.front(); q.pop();
		int nx, ny;
		if(u.time == t)
			break;
		if(u.type == 0 && isalpha(work[u.x][u.y]))
			continue;
		for(int i = 0; i < 4; ++i) {
			nx = u.x + dx[i];
			ny = u.y + dy[i];
			if(nx >= 0 && nx < n && ny >= 0 && ny < n) {
				if(u.type == 0 && !vis[nx][ny] && !isalpha(work[nx][ny])) {
					vis[nx][ny] = 1;
					q.push(Coord(nx, ny, u.time + 1, 0));
				} else if(u.type == 1 && !isalpha(work[nx][ny])) {
					work[nx][ny] = 'Z';
					q.push(Coord(nx, ny, u.time + 1, 1));
				}
			}
		}
	}
}
