            q.push({vdist + 1, {x, y + 1}});
    }
    return dist_map[x2][y2];
}

void connect(int u, int v, int cap) {
    e.push_back({u, v, cap, 0});
    g[u].push_back((int)e.size() - 1);
    e.push_back({v, u, 0, 0});
    g[v].push_back((int)e.size() - 1);
}

bool check_bfs() {
    queue<int> q;
    q.push(0);
    memset(dist, -1, sizeof(dist));
    dist[0] = 0;
    while (!q.empty()) {
        int v = q.front(); q.pop();
        for (auto id : g[v]) {
            int to = e[id].to;
            if (dist[to] == -1 && e[id].flow < e[id].capacity) {
                dist[to] = dist[v] + 1;
                q.push(to);
            }
        }
    }
    return dist[n * n * 2 + 1] != -1;
}

int send(int v, int flow) {
    if (v == n * n * 2 + 1 || flow == 0) return flow;
    for (; ptr[v] < (int)g[v].size(); ptr[v]++) {
        int id = g[v][ptr[v]];
        int to = e[id].to;
        if (dist[to] == dist[v] + 1 && e[id].flow < e[id].capacity) {
            int pushed = send(to, min(flow, e[id].capacity - e[id].flow));
            if (pushed > 0) {
                e[id].flow += pushed;
                e[id ^ 1].flow -= pushed;
                return pushed;
            }
        }
    }
    return 0;
}

int calculate_flow() {
    int total_flow = 0;
    while (check_bfs()) {
        memset(ptr, 0, sizeof(ptr));
        while (int pushed = send(0, INF))
            total_flow += pushed;
    }
    return total_flow;
}

