using namespace std;
typedef long long ll;
struct flow_network {
    struct edge {
        int v, capacity, rev;
    };
    vector<vector<edge>> adj;
    vector<int> level, iter;
    int start, end;
    flow_network(int V, int s, int t): adj(V), level(V), iter(V), start(s), end(t) {}
    void add_edge(int u, int v, int cap) {
        adj[u].push_back({v, cap, (int)adj[v].size()});
        adj[v].push_back({u, 0, (int)adj[u].size() - 1});
    }
    bool build_level() {
        fill(level.begin(), level.end(), -1);
        level[start] = 0;
        queue<int> q; q.push(start);
        while(!q.empty()){
            int u = q.front(); q.pop();
            for(auto &e: adj[u]){
                if(e.capacity > 0 && level[e.v] < 0){
                    level[e.v] = level[u] + 1;
                    q.push(e.v);
                }
            }
        }
        return level[end] >= 0;
    }
    int send_flow(int u, int flow) {
        if(u == end) return flow;
        for(int &i=iter[u]; i<(int)adj[u].size(); i++){
            auto &e = adj[u][i];
            if(e.capacity > 0 && level[e.v] == level[u] + 1){
                int pushed = send_flow(e.v, min(flow, e.capacity));
                if(pushed > 0){
                    e.capacity -= pushed;
                    adj[e.v][e.rev].capacity += pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }
    long long max_flow() {
        long long total=0;
        while(build_level()){
            fill(iter.begin(), iter.end(), 0);
            while(int flow=send_flow(start, INT_MAX)){
                total += flow;
            }
        }
        return total;
    }
};

