#include <bits/stdc++.h>

using namespace std;

const int MAXN = 300;

const int ROOM = -1;
const int REAC = -2;
const int BAD_REAC = -3;
const int CAPS = ROOM;

class Aresta {
public:
    int from, to, rev, flow, cap;
    Aresta(){}
    Aresta(int _from, int _to, int _rev, int _flow, int _cap){
        from = _from; to = _to; rev = _rev; flow = _flow; cap = _cap;
    }
    int residuo() {return cap-flow;}
};

class EdmondsKarp {
public:
    int size;
    vector<Aresta*> *grafo;
    Aresta **prev;
    bool *vis;

    EdmondsKarp(int tam){
        size = tam;
        grafo = new vector<Aresta*>[size];
        prev = new Aresta*[size];
        vis = new bool[size];
    }

    void limpa(){
        for (int i=0; i<size; i++){
            for (size_t j=0; j<grafo[i].size(); j++){
                delete grafo[i][j];
            }
            grafo[i].clear();
        }
    }

    void destroy(){
        limpa();
        delete prev;
        delete vis;
        delete this;
    }

    void add(int s, int t, int cap){
        Aresta *a = new Aresta(s, t, grafo[t].size(), 0, cap);
        Aresta *b = new Aresta(t, s, grafo[s].size(), 0, 0);
        grafo[s].push_back(a);
        grafo[t].push_back(b);
    }

    void undirectedAdd(int s, int t, int cap){
        Aresta *a = new Aresta(s, t, grafo[t].size(), 0, cap);
        Aresta *b = new Aresta(t, s, grafo[s].size(), 0, cap);
        grafo[s].push_back(a);
        grafo[t].push_back(b);
    }

    bool bfs(int source, int sink){
        for (int i=0; i<size; i++){
            prev[i] = NULL;
            vis[i] = false;
        }

        queue<int> fila;
        fila.push(source);
        vis[source] = 1;

        int atual;
        while (!fila.empty()){
            atual = fila.front(); fila.pop();

            if (atual == sink) return true;

            for (Aresta *a : grafo[atual]){
                if (!vis[a->to] && a->residuo() > 0){
                    prev[a->to] = a;
                    vis[a->to] = true;
                    fila.push(a->to);
                }
            }
        }

        return false;
    }

    int dfs(int source, int sink){
        int flow = INT_MAX;
        int v = sink;
        while (v != source){
            flow = min(flow, prev[v]->residuo());
            v = prev[v]->from;
        }

        v = sink;
        Aresta *a;
        while (v != source){
            a = prev[v];
            a->flow += flow;
            grafo[a->to][a->rev]->flow -= flow;
            v = a->from;
        }
        return flow;
    }

    long long int flow(int source, int sink){
        int flow = 0;
        while (bfs(source, sink)){
            flow += dfs(source, sink);
        }
        return flow;
    }
};

int station[MAXN][MAXN], checkpoint[MAXN][MAXN], veneno[61][MAXN][MAXN];

struct coord{
    int x, y, qtd;
    coord(int a, int b, int c){
        x = a; y = b; qtd = c;
    }
    bool is_valid(int N){
        return (x >= 0 && x < N && y >= 0 && y < N && station[x][y] == ROOM);
    }
};

bool is_valid(int x, int y, int N){
    return coord(x, y, 0).is_valid(N);
}

inline bool operator == (const coord &a, const coord &b){
    return (a.x == b.x && a.y == b.y);
}

vector<coord> pessoas, capsulas;
int moveX[] = {-1, 0, 1, 0};  //^<v>
int moveY[] = {0, -1, 0, 1};  //^<v>

int trad(char ch){
    switch (ch) {
        case '0': case '1': case '2': case '3': case '4': case '5': case '6': case '7': case '8': case '9':
            return ROOM;
        case 'Y':
            return REAC;
        case 'Z':
            return BAD_REAC;
    }
    return -1;
}

int how_much(char ch){
    return ch-'0';
}


int bfs(coord from, coord to, int N){
    bitset<MAXN> vis[MAXN];
    queue<pair<int, coord>> fila;
    fila.push({0, from});
    vis[from.x][from.y] = 1;

    while (!fila.empty()){
        int tempo = fila.front().first;
        coord atual = fila.front().second;
        fila.pop();

        if (atual == to) return tempo;

        if (veneno[tempo][atual.x][atual.y]){
            continue;
        }

        for (int i=0; i<4; i++){
            coord next(atual.x + moveX[i], atual.y + moveY[i], 0);
            if (next.is_valid(N) && !vis[next.x][next.y]){
                if (!veneno[tempo][next.x][next.y]){
                    fila.push({tempo + 1, next});
                    vis[next.x][next.y] = 1;
                }
            }
        }
    }

    return 999;
}

void espalha_veneno(int x, int y, int T, int N){
    veneno[0][x][y] = 1;
    for (int i=1; i<=T; i++){
        for (int lin=0; lin<N; lin++){
            for (int col=0; col<N; col++){
                if (veneno[i-1][lin][col]){
                    veneno[i][lin][col] = 1;
                    for (int move=0; move<4; move++){
                        if (is_valid(lin+moveX[move], col+moveY[move], N)){
                            veneno[i][lin+moveX[move]][col+moveY[move]] = 1;
                        }
                    }
                }
            }
        }
    }

}

int main(){
    int N, T;
    scanf(" %d %d", &N, &T);

    char ch;
    coord bad = {0, 0, 0};
    for (int i=0; i<N; i++){
        for (int j=0; j<N; j++){
            scanf(" %c", &ch);
            if (trad(ch) == ROOM && how_much(ch)){
                pessoas.push_back(coord(i, j, how_much(ch)));
            }
            station[i][j] = trad(ch);
            if (station[i][j] == BAD_REAC){
                bad = coord(i, j, 0);
            }
        }
    }

    for (int i=0; i<N; i++){
        for (int j=0; j<N; j++){
            scanf(" %c", &ch);
            if (trad(ch) == CAPS && how_much(ch)){
                capsulas.push_back(coord(i, j, how_much(ch)));
                checkpoint[i][j] = how_much(ch);
            }
        }
    }

    EdmondsKarp *din = new EdmondsKarp(MAXN);
    int sink = MAXN-1;

    for (size_t i=0; i<pessoas.size(); i++){
        din->add(0, i*2+1, pessoas[i].qtd);
    }

    for (size_t i=0; i<capsulas.size(); i++){
        din->add(i*2+2, sink, capsulas[i].qtd);
    }

    espalha_veneno(bad.x, bad.y, T, N);

    for (size_t i=0; i<pessoas.size(); i++){
        for (size_t j=0; j<capsulas.size(); j++){
            int tempo = bfs(pessoas[i], capsulas[j], N);
            if (tempo <= T){
                din->add(i*2+1, j*2+2, 999);
            }
        }
    }

    printf("%lld\n", din->flow(0, sink));
    delete din;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int MAXN = 300;
const int ROOM = -1, REAC = -2, BAD_REAC = -3, CAPS = ROOM;

struct Edge {
    int from, to, rev, flow, cap;
    Edge() {}
    Edge(int f, int t, int r, int fl, int c) : from(f), to(t), rev(r), flow(fl), cap(c) {}
    int residual() { return cap - flow; }
};

class MaxFlow {
public:
    int n;
    vector<Edge*> *graph;
    Edge **parent;
    bool *visited;

    MaxFlow(int size) {
        n = size;
        graph = new vector<Edge*>[n];
        parent = new Edge*[n];
        visited = new bool[n];
    }

    void clear() {
        for (int i=0; i<n; i++) {
            for (auto e : graph[i]) delete e;
            graph[i].clear();
        }
    }

    void destroy() {
        clear();
        delete[] parent;
        delete[] visited;
        delete this;
    }

    void add_edge(int s, int t, int capacity) {
        Edge *a = new Edge(s, t, (int)graph[t].size(), 0, capacity);
        Edge *b = new Edge(t, s, (int)graph[s].size(), 0, 0);
        graph[s].push_back(a);
        graph[t].push_back(b);
    }

    void add_undirected(int s, int t, int capacity) {
        Edge *a = new Edge(s, t, (int)graph[t].size(), 0, capacity);
        Edge *b = new Edge(t, s, (int)graph[s].size(), 0, capacity);
        graph[s].push_back(a);
        graph[t].push_back(b);
    }

    bool bfs(int source, int sink) {
        for (int i=0; i<n; i++) {
            parent[i] = nullptr;
            visited[i] = false;
        }
        queue<int> q;
        q.push(source);
        visited[source] = true;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            if (u == sink) return true;
            for (auto e : graph[u]) {
                if (!visited[e->to] && e->residual() > 0) {
                    parent[e->to] = e;
                    visited[e->to] = true;
                    q.push(e->to);
                }
            }
        }
        return false;
    }

    int dfs(int s, int t) {
        int flow = INT_MAX;
        int v = t;
        while (v != s) {
            flow = min(flow, parent[v]->residual());
            v = parent[v]->from;
        }
        v = t;
        while (v != s) {
            parent[v]->flow += flow;
            graph[parent[v]->to][parent[v]->rev]->flow -= flow;
            v = parent[v]->from;
        }
        return flow;
    }

    long long int max_flow(int s, int t) {
        int total_flow = 0;
        while (bfs(s, t)) {
            total_flow += dfs(s, t);
        }
        return total_flow;
    }
};

int station[MAXN][MAXN], checkpoint[MAXN][MAXN], poison[61][MAXN][MAXN];

struct Coord {
    int x, y, qty;
    Coord(int a, int b, int c) : x(a), y(b), qty(c) {}
    bool valid(int N) { return (x >= 0 && x < N && y >= 0 && y < N && station[x][y] == ROOM); }
};

bool valid_coord(int x, int y, int N) {
    return Coord(x, y, 0).valid(N);
}

inline bool operator==(const Coord &a, const Coord &b) {
    return (a.x == b.x && a.y == b.y);
}

vector<Coord> people, capsules;
int dx[] = {-1, 0, 1, 0};
int dy[] = {0, -1, 0, 1};

int translate_char(char ch) {
    if (ch >= '0' && ch <= '9') return ROOM;
    if (ch == 'Y') return REAC;
    if (ch == 'Z') return BAD_REAC;
    return -1;
}

int get_quantity(char ch) {
    return ch - '0';
}

int bfs_path(Coord start, Coord end, int N) {
    bitset<MAXN> visited[MAXN];
    queue<pair<int, Coord>> q;
    q.push({0, start});
    visited[start.x][start.y] = 1;
    while (!q.empty()) {
        int time = q.front().first;
        Coord curr = q.front().second;
        q.pop();
        if (curr == end) return time;
        if (poison[time][curr.x][curr.y]) continue;
        for (int i=0; i<4; i++) {
            Coord next(curr.x + dx[i], curr.y + dy[i], 0);
            if (next.valid(N) && !visited[next.x][next.y]) {
                if (!poison[time][next.x][next.y]) {
                    q.push({time + 1, next});
                    visited[next.x][next.y] = 1;
                }
            }
        }
    }
    return 999;
}

void spread_poison(int x, int y, int T, int N) {
    poison[0][x][y] = 1;
    for (int t=1; t<=T; t++) {
        for (int i=0; i<N; i++) {
            for (int j=0; j<N; j++) {
                if (poison[t-1][i][j]) {
                    poison[t][i][j] = 1;
                    for (int move=0; move<4; move++) {
                        int nx = i + dx[move], ny = j + dy[move];
                        if (valid_coord(nx, ny, N))
                            poison[t][nx][ny] = 1;
                    }
                }
            }
        }
    }
}

int main() {
    int N, T;
    scanf("%d %d", &N, &T);
    char ch;
    Coord bad(0,0,0);
    for (int i=0; i<N; i++) {
        for (int j=0; j<N; j++) {
            scanf(" %c", &ch);
            int val = translate_char(ch);
            station[i][j] = val;
            if (val == ROOM && get_quantity(ch))
                people.push_back(Coord(i,j,get_quantity(ch)));
            if (val == BAD_REAC)
                bad = Coord(i,j,0);
        }
    }
    for (int i=0; i<N; i++) {
        for (int j=0; j<N; j++) {
            scanf(" %c", &ch);
            int val = translate_char(ch);
            if (val == CAPS && get_quantity(ch)) {
                capsules.push_back(Coord(i,j,get_quantity(ch)));
                checkpoint[i][j] = get_quantity(ch);
            }
        }
    }
    MaxFlow *mf = new MaxFlow(MAXN);
    int sink = MAXN - 1;
    for (size_t i=0; i<people.size(); i++) {
        mf->add_edge(0, i*2+1, people[i].qty);
    }
    for (size_t i=0; i<capsules.size(); i++) {
        mf->add_edge(i*2+2, sink, capsules[i].qty);
    }
    spread_poison(bad.x, bad.y, T, N);
    for (size_t i=0; i<people.size(); i++) {
        for (size_t j=0; j<capsules.size(); j++) {
            int time_needed = bfs_path(people[i], capsules[j], N);
            if (time_needed <= T) {
                mf->add_edge(i*2+1, j*2+2, 999);
            }
        }
    }
    printf("%lld\n", mf->max_flow(0, sink));
    delete mf;
    return 0;
}

#include <bits/stdc++.h>
