    cin >> n >> t;
    vector<string> s1(n), s2(n);
    for (int i = 0; i < n; i++) cin >> s1[i];
    for (int i = 0; i < n; i++) cin >> s2[i];

    int rx = -1, ry = -1;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (s1[i][j] == 'Z') {
                rx = i;
                ry = j;
            }
        }
    }

    vector<vector<int>> reac_dist = get_bfs_distances(rx, ry, s1);

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (!is_valid_cell(i, j, s1)) continue;
            vector<vector<int>> from_cell = get_bfs_distances(i, j, s1);
            for (int x = 0; x < n; x++) {
                for (int y = 0; y < n; y++) {
                    if (!is_valid_cell(x, y, s1) || from_cell[x][y] > t || from_cell[x][y] > reac_dist[x][y]) continue;
                    if (from_cell[x][y] == reac_dist[x][y]) {
                        bool can_move = false;
                        for (int dir_idx = 0; dir_idx < 4; dir_idx++) {
                            int xto = x + dir_x[dir_idx];
                            int yto = y + dir_y[dir_idx];
                            if (!is_valid_cell(xto, yto, s1) || from_cell[xto][yto] >= reac_dist[xto][yto]) continue;
                            can_move = true;
                        }
                        if (!can_move) continue;
                    }
                    int max1 = s1[i][j] - '0';
                    int max2 = s2[x][y] - '0';
                    for (int num1 = 1; num1 <= max1; num1++) {
                        for (int num2 = 1; num2 <= max2; num2++) {
                            int v1 = 10 * (j + i * 10) + num1;
                            int v2 = 10 * (y + 10 * x) + num2;
                            graph[v1].push_back(v2);
                        }
                    }
                }
            }
        }
    }
}

bool dfs_match(int v) {
    if (visited[v]) return false;
    visited[v] = true;
    for (int to : graph[v]) {
        if (match[to] == 0 || dfs_match(match[to])) {
            match[to] = v;
            return true;
        }
    }
    return false;
}

void solve_problem() {
    build_graph_from_input();
    int total_nodes = max_n;
    for (int i = 0; i < total_nodes; i++) {
        dfs_match(i);
        fill(visited, visited + total_nodes, false);
    }
    int total_matches = 0;
    for (int i = 0; i < total_nodes; i++) {
        if (match[i] != 0) total_matches++;
    }
    cout << total_matches;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);
    solve_problem();
}

