bool is_valid_cell(int x, int y, const vector<string>& grid) {
    int n = (int)grid.size();
    return x >= 0 && y >= 0 && x < n && y < n && grid[x][y] != 'Y' && grid[x][y] != 'Z';
}

vector<vector<int>> compute_bfs(int start_x, int start_y, const vector<string>& grid) {
    int n = (int)grid.size();
    vector<vector<int>> dist(n, vector<int>(n, INF));
    dist[start_x][start_y] = 0;
    deque<pii> q;
    q.push_back({start_x, start_y});
    while (!q.empty()) {
        auto [x, y] = q.front();
        q.pop_front();
        for (int d = 0; d < 4; d++) {
            int nx = x + dir_x[d], ny = y + dir_y[d];
            if (!is_valid_cell(nx, ny, grid) || dist[nx][ny] != INF) continue;
            dist[nx][ny] = dist[x][y] + 1;
            q.push_back({nx, ny});
        }
    }
    return dist;
}

