pair<int, int> q[N];
int dx[4] = {0, -1, 0, 1};
int dy[4] = {1, 0, -1, 0};

void add_edge(int u, int v, int uv, int vu) {
	from[ec] = u, to[ec] = v, cap[ec] = uv, prev[ec] = head[u], head[u] = ec++;
	from[ec] = v, to[ec] = u, cap[ec] = vu, prev[ec] = head[v], head[v] = ec++;
}

int dfs(int v, int sink, int flow = 2e9) {
	if (v == sink)
		return flow;
