struct dinic{
	int fst[N], vv[M], nxt[M], cap[M], flow[M], e;
	int d[N], cur[N];
	int s, t;
	void init(){
		memset(fst, -1, sizeof fst); e = 0;
	}
	void add(int u, int v, int c){
		vv[e] = v, nxt[e] = fst[u], cap[e] = c, flow[e] = 0, fst[u] = e++;
		vv[e] = u, nxt[e] = fst[v], cap[e] = 0, flow[e] = 0, fst[v] = e++;
	}
	bool bfs(){
	   	memset(d, -1, sizeof d);
   	   	d[s] = 0;
		queue<int> q;
		q.push(s);
		while(!q.empty()){
			int u = q.front(); q.pop();
			for(int i = fst[u]; ~i; i = nxt[i]){
				int v = vv[i];
				if(d[v] == -1 && cap[i] > flow[i]){
					d[v] = d[u] + 1;
					q.push(v);
				}
			}
		}
		return d[t] != -1;
	}
	int dfs(int u, int a){
		if(u == t || a == 0) return a;
		int ret = 0, f;
		for(int &i = cur[u]; ~i; i = nxt[i]){
			int v = vv[i];
			if(d[v] == d[u] + 1 && (f = dfs(v, min(a, cap[i] - flow[i]))) > 0){
				a -= f;
				ret += f;
				flow[i] += f;
				flow[i^1] -=f;
				if(a == 0) break;
			}
		}
		return ret;
	}
	int gao(int _s, int _t){
		s = _s, t = _t;
		int ret = 0;
		while(bfs()){
			memcpy(cur, fst, sizeof fst);
			ret += dfs(s, inf);
		}
		return ret;
	}
}go;
int d[4][2] = {-1, 0, 0, 1, 1, 0, 0, -1};
int dis[12][12], tim[12][12];
char g[N][N], h[N][N];
int n, t;
bool in(int x, int y){
	return x >= 0 && x < n && y >= 0 && y < n;
}
void bfs1(int sx, int sy){
	memset(tim, 0x3f, sizeof tim);
	queue<int> q;
	q.push(sx * 10 + sy);
	tim[sx][sy] = 0;
	while(!q.empty()){
		int x = q.front() / 10, y = q.front() % 10;
	   	q.pop();
		for(int i = 0; i < 4; ++i){
			int nx = x + d[i][0], ny = y + d[i][1];
			if(in(nx, ny) && g[nx][ny] >= '0' && g[nx][ny] <= '9' && tim[nx][ny] > tim[x][y] + 1){
				tim[nx][ny]	= tim[x][y] + 1;
				q.push(nx * 10 + ny);
			}
		}
	}
}
void bfs2(int sx, int sy){
	memset(dis, 0x3f, sizeof dis);
	queue<int> q;
	q.push(sx * 10 + sy);
	dis[sx][sy] = 0;
	while(!q.empty()){
		int x = q.front() / 10, y = q.front() % 10;
		q.pop();
		for(int i = 0; i < 4; ++i){
			int nx = x + d[i][0], ny = y + d[i][1];
			if(in(nx, ny) && h[nx][ny] >= '0' && h[nx][ny] <= '9' && dis[nx][ny] > dis[x][y] + 1){
				if(h[nx][ny] >= '0' && tim[nx][ny] >= dis[x][y] + 1){
					dis[nx][ny] = dis[x][y] + 1;
					if(tim[nx][ny] > dis[nx][ny])
						q.push(nx * 10 + ny);
				}
			}
		}
	}
}
int main(){
	scanf("%d%d", &n, &t);
	for(int i = 0; i < n; ++i)
		scanf("%s", g[i]);
	for(int i = 0; i < n; ++i)
		scanf("%s", h[i]);
	for(int i = 0; i < n; ++i)
		for(int j = 0; j < n; ++j)
			if(g[i][j] == 'Z')
				bfs1(i, j);
	int S = 0, T = n * n * 2 + 1;
	go.init();
	for(int i = 0; i < n; ++i)
		for(int j = 0; j < n; ++j){
			if(g[i][j] > '0' && g[i][j] <= '9')
				go.add(S, i * n + j + 1, g[i][j] - '0');
			if(h[i][j] > '0' && h[i][j] <= '9')
				go.add(n * n + i * n + j + 1, T, h[i][j] - '0');
		}
	for(int i = 0; i < n; ++i)
		for(int j = 0; j < n; ++j)
			if(g[i][j] > '0' && g[i][j] <= '9'){
				bfs2(i, j);
				for(int x = 0; x < n; ++x)
					for(int y = 0; y < n; ++y){
						if(h[x][y] > '0' && h[x][y] <= '9' && dis[x][y] <= t){
							go.add(i * n + j + 1, n * n + x * n + y + 1, inf);
						}
					}
			}
	int ret = go.gao(S, T);
	printf("%d\n", ret);
	return 0;
}

