#include <queue>
#include <cstring>
using namespace std;

int readNumber() {
    int x; cin >> x; return x;
}
string readLine() {
    string s; cin >> s; return s;
}

struct Edge {
    int from, to, capacity, flow;
};

vector<Edge> edges;
vector<int> g[100000];
int distA[31][31], distB[31][31];
int dx[] = {0, 0, -1, 1};
int dy[] = {1, -1, 0, 0};
int n, t;
string a[30], b[30];
int startX, startY;
int s, t_;
int level[100000], ptr[100000], q[100000];

void addEdge(int u, int v, int cap) {
    edges.push_back({u, v, cap, 0});
    g[u].push_back((int)edges.size() - 1);
    edges.push_back({v, u, 0, 0});
    g[v].push_back((int)edges.size() - 1);
}

bool validPos(int x, int y) {
    return x >= 0 && x < n && y >= 0 && y < n;
}

void BFS1(int x=0, int y=0) {
    queue<pair<int,int>> q;
    q.push({x, y});
    for (int i=0; i<=20; ++i)
        for (int j=0; j<=20; ++j)
            distA[i][j]=1e9;
    distA[x][y]=0;
    while (!q.empty()) {
        auto [cx, cy]=q.front(); q.pop();
        for (int i=0; i<4; ++i) {
            int nx=cx+dx[i], ny=cy+dy[i];
            if (validPos(nx, ny) && distA[nx][ny]>=1e9 && b[nx][ny]!='Y') {
                distA[nx][ny]=distA[cx][cy]+1;
                q.push({nx, ny});
            }
        }
    }
}

bool BFS() {
    memset(level, -1, sizeof(level));
    int front=0, back=0;
    q[back++]=s;
    level[s]=0;
    while (front<back && level[t_]==-1) {
        int v=q[front++];
        for (int id : g[v]) {
            int to=edges[id].to;
            if (level[to]==-1 && edges[id].flow<edges[id].capacity) {
                level[to]=level[v]+1;
                q[back++]=to;
            }
        }
    }
    return level[t_]!=-1;
}

int sendFlow(int v, int flow) {
    if (v==t_) return flow;
    for (int &i=ptr[v]; i<(int)g[v].size(); ++i) {
        int id=g[v][i];
        int to=edges[id].to;
        if (level[to]!=level[v]+1 || edges[id].flow>=edges[id].cap) continue;
        int pushed=sendFlow(to, min(flow, edges[id].cap - edges[id].flow));
        if (pushed>0) {
            edges[id].flow+=pushed;
            edges[id^1].flow-=pushed;
            return pushed;
        }
    }
    return 0;
}

int maxFlow() {
    int total=0;
    while (BFS()) {
        for (int i=0; i<(int)edges.size(); ++i) ptr[i]=0;
        while (int pushed=sendFlow(s,1e9))
            total+=pushed;
    }
    return total;
}

void BFS2(int x, int y) {
    queue<pair<int,int>> q;
    q.push({x, y});
    for (int i=0; i<=20; ++i)
        for (int j=0; j<=20; ++j)
            distB[i][j]=1e9;
    distB[x][y]=0;
    while (!q.empty()) {
        auto [cx, cy]=q.front(); q.pop();
        if (distB[cx][cy]>=distA[cx][cy]) continue;
        for (int i=0; i<4; ++i) {
            int nx=cx+dx[i], ny=cy+dy[i];
            if (validPos(nx, ny) && distB[nx][ny]>=1e9 && a[nx][ny]!='Y' && distB[cx][cy]+1<=distA[nx][ny]) {
                distB[nx][ny]=distB[cx][cy]+1;
                q.push({nx, ny});
            }
        }
    }
}

int main() {
    n=getNumber(); t=getNumber();
    for (int i=0; i<n; ++i) a[i]=getLine();
    for (int i=0; i<n; ++i) {
        b[i]=getLine();
        for (int j=0; j<n; ++j) {
            if (b[i][j]=='Z') {
                b[i][j]='Y'; a[i][j]='Y';
                startX=i; startY=j;
            }
        }
    }
    BFS1();
    s=0; t_=2*n*n+1;
    for (int i=0; i<n; ++i) {
        for (int j=0; j<n; ++j) {
            if (a[i][j]=='Y') continue;
            int inNode=i*n+j+1;
            int outNode=n*n+i*n+j+1;
            addEdge(s, inNode, a[i][j]-'0');
            addEdge(outNode, t_, b[i][j]-'0');
            BFS2(i,j);
            for (int ptx=0; ptx<n; ++ptx) {
                for (int pty=0; pty<n; ++pty) {
                    if (b[ptx][pty]=='Y' || distB[ptx][pty]>t) continue;
                    addEdge(inNode, n*n+ptx*n+pty+1, a[i][j]-'0');
                }
            }
        }
    }
    cout << maxFlow() << endl;
    return 0;
}

