	return ch>='1' && ch <='9';
}
void bfs(int x, int y, int d[][N], bool f) {
	int sx = x, sy = y;
	fill(d[0], d[N], inf);
	d[x][y] = 0;
	queue<int> Q;
	Q.push(x);
	Q.push(y);
	if(f && isdigit(capsule[x][y])) {
		F.add(sx*n+sy, sx*n+sy+n*n, inf);
	}
	while(!Q.empty()) {
		x = Q.front();
