    for (int j = 1; j <= n; ++j) {
        int lower_bound = (j * a) / b - 1;
        int upper_bound = (j * a) / b + 1;
        for (int i = lower_bound; i <= upper_bound; ++i) {
            double diff = fabs((double)i / j - (double)a / b);
            if (diff < closest_diff) {
                closest_diff = diff;
                numerator = i;
                denominator = j;
            }
        }
    }
    int g = compute_gcd(abs(numerator), denominator);
    cout << numerator / g << "/" << denominator / g;
    return 0;
}

