float Tabs(double n){
    if(n>=0) return n;
    return -n;
}

int solve_it(int x,int y,int b){
    double target = (double)x/y;
    int lb=0,ub=1000000;
    for(int i=0; i<25; i++){
        int a = (lb+ub)/2;
        if((double)a/b < target) lb = a;
        else ub = a;
    }
    int res;
    double diff=DBL_MAX;
    for(int a=lb-10; a<=ub+10; a++){
        double d = Tabs((double)a/b - target);
        if(d < diff){
            diff = d;
            res = a;
        }
    }
    return res;
}

int main(){
    int x,y,n;
    scanf("%d %d %d",&x,&y,&n);
    int ans1,ans2;
    double best_diff=DBL_MAX;
    for(int b=1; b<=n; b++){
        int a = solve_it(x,y,b);
        double d = Tabs((double)a/b - (double)x/y);
        if(d < best_diff) {
            best_diff = d;
            ans1 = a; ans2 = b;
        }
    }
    printf("%d/%d\n",ans1,ans2);
    return 0;
}

