long long find_gcd(long long a, long long b) {
    while (b != 0) {
        long long t = b;
        b = a % b;
        a = t;
    }
    return a;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    cin >> A1 >> B1 >> C1;

    if (B1 <= C1) {
        long long g = find_gcd(A1, B1);
        A1 /= g;
        B1 /= g;
        cout << A1 << "/" << B1;
        return 0;
    }
    if (A1 == B1) {
        cout << "1/1";
        return 0;
    }

