inline int input() {
    int sign=1, val=0; char ch=getchar();
    while (ch<'0'||ch>'9') { if (ch=='-') sign=-1; ch=getchar(); }
    while (ch>='0'&&ch<='9') { val=val*10+ch-48; ch=getchar(); }
    return sign*val;
}

inline int min_of_two(reg int a, reg int b) { return a<b?a:b; }
inline int max_of_two(reg int a, reg int b) { return a>b?a:b; }

const int MAX_LIMIT=2000010, MOD_A=1000000007, MOD_B=998244353, BASE_NUM=1000000;
int total_nums, current_idx, total_ans, prefix_sum_arr[10];
vector<int> digit_buckets[10];

inline int mod_calc(reg int x) { return (x%MOD_B+MOD_B)%MOD_B; }

void build_sequence(reg int start, reg int depth) {
    ++total_nums;
    digit_buckets[depth].push_back(mod_calc(total_nums - start));
    (total_ans += digit_buckets[depth].back()) %= MOD_A;
    if (depth==6) return;
    for (reg int d=0; d<10; d++) build_sequence(start*10+d, depth+1);
}

void traverse(reg int num) {
    if (num > n) return;
    if (num*BASE_NUM + (BASE_NUM-1) <= n && num*BASE_NUM*10 > n) {
        reg int prev_idx=total_nums;
        for (reg int level=0, mult=1; level<=6; level++, mult*=10) {
            reg int size=digit_buckets[level].size();
            reg int delta=mod_calc(prev_idx - num*mult);
            reg int pos=lower_bound(digit_buckets[level].begin(), digit_buckets[level].end(), MOD_B - delta) - digit_buckets[level].begin();
            total_ans=(total_ans + delta*size + prefix_sum_arr[level] - MOD_B*(size - pos))%MOD_A;
            total_nums+=size;
        }
        return;
    }
    ++total_nums;
    total_ans=(total_ans + mod_calc(total_nums - num))%MOD_A;
    for (reg int d=0; d<10; d++) traverse(num*10+d);
}

signed main() {
    n=input();
    build_sequence(0,0);
    for (reg int i=0; i<=6; i++) sort(digit_buckets[i].begin(), digit_buckets[i].end());
    total_nums=0;
    for (reg int i=1; i<=9; i++) traverse(i);
    printf("%lld", (total_ans+MOD_A)%MOD_A);
    return 0;
}

