#include <bits/stdc++.h>
using namespace std;

using LL = long long;
const int DEPTH_LIMIT = 7, MAX_BASE = 1000000, MOD_A = 998244353, MOD_B = 1000000007;
LL total_input_value, total_counter;
vector<int> digit_collections[DEPTH_LIMIT];
int final_result, prefix_sums[DEPTH_LIMIT];

int main() {
    scanf("%lld", &total_input_value);
    function<void(int, int)> generate_numbers = [&](int level, int val) {
        digit_collections[level].push_back((++total_counter - val + MOD_A) % MOD_A);
        if (level == 6) return;
        for (int digit = 0; digit < 10; ++digit) {
            generate_numbers(level + 1, val * 10 + digit);
        }
    };
    generate_numbers(0, 0);
    for (int d = 0; d <= 6; ++d) {
        sort(digit_collections[d].begin(), digit_collections[d].end());
        for (auto v : digit_collections[d]) (prefix_sums[d] += v) %= MOD_B;
    }
    function<void(int, LL)> process_node = [&](int depth, LL v) {
        if (v > total_input_value) return;
        if (depth != 0) {
            if (v * MAX_BASE > total_input_value / 10 && (v + 1) * MAX_BASE - 1 <= total_input_value) {
                for (int i = 0, pwr = 1; i <= 6; ++i, pwr *= 10) {
                    int coef = (total_counter - 1LL * v * pwr % MOD_A + MOD_A) % MOD_A;
                    auto it = lower_bound(digit_collections[i].begin(), digit_collections[i].end(), MOD_A - coef);
                    final_result = (final_result + 1LL * coef * digit_collections[i].size() + prefix_sums[i]) % MOD_B;
                    final_result = (final_result - 1LL * MOD_A * (digit_collections[i].end() - it) % MOD_B + MOD_B) % MOD_B;
                }
                for (int i = 0; i <= 6; ++i) total_counter += digit_collections[i].size();
                return;
            }
            final_result = (final_result + (++total_counter - v % MOD_A + MOD_A) % MOD_A) % MOD_B;
        }
        for (int c = (depth == 0 ? 1 : 0); c < 10; ++c) {
            process_node(depth + 1, v * 10 + c);
        }
    };
    total_counter = 0; process_node(0, 0);
    printf("%d\n", final_result);
    return 0;
}

