const int mod1=998244353;
const int mod2=1000000007;
const int NN=1000100;

vector<int> s[7];
INT sum[7];
INT nxt(INT val, INT n) {
    if (val * 10 <= n) return val * 10;
    else {
        val++;
        if (val <= n) while (val % 10 == 0) val /= 10;
        else {
            val = (val - 1) / 10 + 1;
            while (val % 10 == 0) val /= 10;
        }
    }
    return val;
}

int L[NN];

void pre() {
    int val = 0, len = 1;
    int nth = 1;
    for (int i = 1; i <= 1111110; i++) {
        s[len].push_back(D(nth, val));
        nth++;
        if (len < 6) {
            len++;
            val *= 10;
        } else {
            val++;
            while (val % 10 == 0) val /= 10, len--;
        }
    }
    for (int i = 1; i <= 6; i++) {
        sort(s[i].begin(), s[i].end());
        for (auto v : s[i]) sum[i] = (sum[i] + v) % mod2;
    }
    int ed = 1, f = 0;
    for (int i = 1; i <= 1000000; i++) {
        if (i == ed) ed *= 10, f++;
        L[i] = f;
    }
}

INT NTH;
INT calc(INT val, INT nth, INT n) {
    INT ans = 0;
    INT st = val / 100;
    st++;
    while (st % 10 == 0) st /= 10;
    while (val != st) {
        ans = (ans + D(nth, val)) % mod2;
        nth++;
        val = nxt(val, n);
    }
    NTH = nth;
    return ans;
}

int main() {
#ifndef ONLINE_JUDGE
    freopen("in.in", "r", stdin);
    freopen("out.out", "w", stdout);
#endif
    pre();

    INT n;
    cin >> n;
    if (n < 10000000) {
        INT ans = 0;
        INT val = 1;
        for (int i = 1; i <= n; i++) {
            ans = (ans + D(i, val)) % mod2;
            if (i == n) break;
            val = nxt(val, n);
        }
        cout << ans << endl;
        return 0;
    }

    INT ans = 0;
    INT val = 1, nth = 1;
    int N = n / 1000000;
    while (true) {
        ans = (ans + D(nth, val)) % mod2;
        nth++;
        if (L[val] == L[N]) {
            if (val == N) {
                ans = (ans + calc(val * 10, nth, n)) % mod2;
                nth = NTH;
                break;
            }
            INT v = val;
            for (int i = 1; i <= 6; i++) {
                v *= 10;
                INT del = D(nth - 1, v);
                int N_idx = lower_bound(s[i].begin(), s[i].end(), mod1 - del) - s[i].begin();
                N_idx -= s[i].size();
                ans = (ans + sum[i] + 1LL * N_idx * mod1) % mod2;
                ans = (ans + mod2) % mod2;
                ans = (ans + del * s[i].size()) % mod2;
            }
            nth += 1111110;
        }
        val = nxt(val, N);
    }

    n = 1;
    int limit = 1;
    for (int i = 0; i < L[N] + 6; i++) limit *= 10;
    limit--;
    N = limit / 1000000;

    val /= 10;
    val++;
    while (val % 10 == 0) val /= 10;

    while (val != 1) {
        ans = (ans + D(nth, val)) % mod2;
        nth++;
        if (L[val] == L[N]) {
            INT v = val;
            for (int i = 1; i <= 6; i++) {
                v *= 10;
                INT del = D(nth - 1, v);
                int N_idx = lower_bound(s[i].begin(), s[i].end(), mod1 - del) - s[i].begin();
                N_idx -= s[i].size();
                ans = (ans + sum[i] + 1LL * N_idx * mod1) % mod2;
                ans = (ans + mod2) % mod2;
                ans = (ans + del * s[i].size()) % mod2;
            }
            nth += 1111110;
        }
        val = nxt(val, N);
    }
    cout << ans << endl;
    return 0;
}

