    vector<long long> power_of_10(17, 1);
    for (int i = 1; i < 17; ++i) power_of_10[i] = power_of_10[i - 1] * 10;

    auto convert_to_string = [](long long x) {
        if (x == 0) return string("0");
        string res;
        while (x > 0) {
            res += '0' + x % 10;
            x /= 10;
        }
        reverse(res.begin(), res.end());
        return res;
    };

    long long total_result = 0;
    for (int length = 1; length <= (int)num_str.size(); ++length) {
        long long base_sum = 0;
        string prefix_str;
        for (int diff_idx = 0; diff_idx < (int)num_str.size() && diff_idx < length; ++diff_idx) {
            if (diff_idx > 0) {
                base_sum = base_sum * 10 + (num_str[diff_idx - 1] - '0');
                prefix_str += num_str[diff_idx - 1];
            }
            for (int last_digit = 0; last_digit <= 9; ++last_digit) {
                if (diff_idx == 0 && last_digit == 0) continue;
                if (last_digit == (num_str[diff_idx] - '0')) continue;
                if (length == (int)num_str.size() && last_digit > (num_str[diff_idx] - '0')) continue;

                long long prefix_value = base_sum * 10 + last_digit;
                string current_prefix = prefix_str + (char)('0' + last_digit);

                long long prefix_sum_value = 0;
                for (char c : current_prefix) {
                    prefix_sum_value = prefix_sum_value * 10 + (c - '0');
                }

                long long smaller_count = 0;
                string temp_str;
                for (int pos = 0; pos < (int)current_prefix.size(); ++pos) {
                    for (char d = (pos == 0 ? '1' : '0'); d < current_prefix[pos]; ++d) {
                        string s2 = temp_str + d;
                        long long v = 0;
                        for (char ch : s2) v = v * 10 + (ch - '0');
                        smaller_count += power_of_10[(int)s2.size()] - v * power_of_10[(int)s2.size() - 1];
                    }
                    temp_str += current_prefix[pos];
                }
                prefix_sum_value += length - 1;

                vector<long long> vars;
                string tmp2 = temp_str;
                for (int pos = (int)tmp2.size(); pos < length; ++pos) {
                    long long val = 0;
                    for (char d = '0'; d <= '9'; ++d) {
                        string s2 = tmp2 + d;
                        long long v = 0;
                        for (char ch : s2) v = v * 10 + (ch - '0');
                        val += v;
                    }
                    vars.push_back(val % 998244353);
                    tmp2 += '0';
                }

                long long res = 0;
                for (auto v : vars) {
                    res += (smaller_count + v) % 998244353;
                }
                total_result += res % 998244353;
            }
        }
    }
    cout << convert_to_string(total_result % 1000000007) << "\n";
    return 0;
}

