long long power_mod(long long base, long long exp, long long mod) {
    long long result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) result = result * base % mod;
        base = base * base % mod;
        exp >>= 1;
    }
    return result;
}

vector<int> berlekamp_massey(const vector<int>& sequence) {
    vector<int> ls, cur;
    int lf, ld;
    for (int i = 0; i < (int)sequence.size(); ++i) {
        long long t = 0;
        for (int j = 0; j < (int)cur.size(); ++j)
            t = (t + sequence[i - j - 1] * (long long)cur[j]) % 998244353;
        if ((t - sequence[i]) % 998244353 == 0) continue;
        if (cur.empty()) {
            cur.resize(i + 1);
            lf = i;
            ld = (t - sequence[i]) % 998244353;
            continue;
        }
        long long k = - (sequence[i] - t) * power_mod(ld, 998244351, 998244353) % 998244353;
        vector<int> c(i - lf - 1, 0);
        c.push_back(k);
