LL n, A[20], B[20], min_cost;
#define FOR_LOOP(i,a,b) for(int i=(a);i<=(b);i++)

void recurse(int position, LL current_value, LL total_cost) {
    if (total_cost >= min_cost) return;
    if (position == 0) {
        if (current_value == 0) min_cost = total_cost;
        return;
    }
    int q = current_value / A[position];
    int diff_neg = abs(q) - 1;
    if (q < 0) diff_neg = -diff_neg;
    int diff_pos = abs(q) + 1;
    if (q < 0) diff_pos = -diff_pos;

    recurse(position - 1, current_value - q * B[position], total_cost + abs(q) * position);
    recurse(position - 1, current_value - diff_neg * B[position], total_cost + abs(diff_neg) * position);
    recurse(position - 1, current_value - diff_pos * B[position], total_cost + abs(diff_pos) * position);
}

int main() {
    for (int i=1; i<=16; i++) B[i] = B[i-1]*10+1;
    A[1] = 1;
    for (int i=2; i<=16; i++) A[i] = A[i-1]*10;
    scanf("%lld", &n);
    LL temp_num = n;
    int digit_count = 0;
    while (temp_num) {
        digit_count++;
        temp_num /= 10;
    }
    min_cost = 1e18;
    recurse(digit_count, n, 0);
    recurse(digit_count, B[digit_count+1] - n, digit_count+1);
    printf("%lld\n", min_cost);
    return 0;
}

