#include <bits/stdc++.h>
using namespace std;

vector<long long> ones(20), powers(20);
int min_moves = -1;

void prepare()
{
    powers[0] = 1;
    for (int i = 1; i <= 17; ++i)
        powers[i] = powers[i - 1] * 10;

    ones[0] = 0;
    for (int i = 1; i <= 17; ++i)
        ones[i] = ones[i - 1] * 10 + 1;
}

int get_length(long long num)
{
    int len = 0;
    do
    {
        ++len;
        num /= 10;
    } while (num != 0);
    return len;
}

void recurse(int digit_pos, long long val, int steps)
{
    if (min_moves != -1 && steps >= min_moves)
        return;
    if (val == 0 || digit_pos == 0)
    {
        if (min_moves == -1 || steps < min_moves)
            min_moves = steps;
        return;
    }
    if (val < 0)
        val = -val;

    long long temp_val = val;
    int temp_steps = 0;
    while (temp_val >= powers[digit_pos - 1])
    {
        temp_val -= ones[digit_pos];
        temp_steps += digit_pos;
    }
    recurse(digit_pos - 1, temp_val, steps + temp_steps);

    temp_val = ones[digit_pos + 1] - val;
    temp_steps = 0;
    while (temp_val >= powers[digit_pos - 1])
    {
        temp_val -= ones[digit_pos];
        temp_steps += digit_pos;
    }
    recurse(digit_pos - 1, temp_val, steps + digit_pos + 1 + temp_steps);
}

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    prepare();

    long long number;
    cin >> number;
    min_moves = -1;
    recurse(get_length(number), number, 0);
    cout << min_moves << "\n";

    return 0;
}

