    string result = "";
    int n = s.size();

    for (int i = 0; i < n; ++i) {
        if (i + 3 <= n && s.substr(i, 3) == "dot") {
            result += '.';
            i += 2;
        } else if (i + 2 <= n && s.substr(i, 2) == "at") {
            result += '@';
            i += 1;
        } else {
            result += s[i];
        }
    }

    auto replace_end = [&](char c, string replacement) {
        if (!result.empty() && result.back() == c) {
            result.pop_back();
            result += replacement;
        }
    };

    replace_end('.', "dot");
    replace_end('@', "at");

    int at_count = count(result.begin(), result.end(), '@');

    if (at_count == 1) {
        cout << result << endl;
    } else {
        bool first_at = true;
        for (char ch : result) {
            if (ch == '@') {
                if (first_at) {
                    cout << '@';
                    first_at = false;
                } else {
                    cout << "at";
                }
            } else {
                cout << ch;
            }
        }
        cout << endl;
    }
    return 0;
}

