typedef Field<1000000007> FieldMod;

struct Ring {
    template <typename T>
    static T div(T p, T q, T N) {
        T t = 0, nt = 1, r = N, nr = q;
        while (nr != 0) { T q = r / nr; t -= q * nt; swap(t, nt); r -= q * nr; swap(r, nr); }
        t = (t < 0) ? t + N : t;
        r = (r < 0) ? r + N : r;
        if (gcd(p, N) % r != 0) { return 0; }
        return (t * p / r) % N;
    }
};
