			if((i&x)==0){
				d_nums[i^x]+=d_nums[i];
			}
		}
	}
	//cout<<3<<endl;
	Mod answer=0;
	for(int i=0;i<(1<<20);++i){
		if(u_nums[i].num){
			//WHATS(i)
			int need=0;
			{
				for(int x=0;x<20;++x){
					if(i&(1<<x)){
						need|=(1<<(19-x));
					}
				}
			}
			//WHATS(u_nums[i].num)
			int pp=((1<<20)-1)^i;
			//WHATS(pp)

			Mod nanswer=u_nums[i]*(Mod(1)-d_nums[((1<<20)-1)^need]);
			answer+=nanswer;
		}
	}
	cout<<answer.num<<endl;

	return 0;
}

