int main() {
    int size;
    scanf("%d", &size);
    int matrix[6][6];
    for (int row = 0; row < size; row++) {
        for (int col = 0; col < size; col++) {
            scanf("%d", &matrix[row][col]);
        }
    }

    vector<int> maskH, maskH2;
    int halfH = (size + 1) / 2;
    int halfH2 = size - halfH;
    int inv100 = modularInverse(100);

    for (int mask = 0; mask < (1 << size); mask++) {
        int countBits = __builtin_popcount(mask);
        if (countBits == halfH) maskH.push_back(mask);
        if (countBits == halfH2) maskH2.push_back(mask);
    }

    vector<LLI> probability((1 << (size * halfH)), 0);
    vector<LLI> probability2((1 << (size * halfH2)), 0);

    for (int subsetMask = 0; subsetMask < (1 << (size * halfH)); subsetMask++) {
        LLI probProduct = 1;
        for (int j = 0; j < size * halfH; j++) {
            int rowIdx = j / size, colIdx = j % size;
            if (subsetMask & (1 << j))
                probProduct = (probProduct * ((LLI) matrix[rowIdx][colIdx] * inv100) % MOD) % MOD;
            else
                probProduct = (probProduct * ((LLI) (100 - matrix[rowIdx][colIdx]) * inv100) % MOD) % MOD;
        }
