                    int a = k * size + v[k];
                    if (!(subsetMask & (1 << a))) break;
                }
                if (k == (int)v.size()) {
                    possibleStates |= (1 << j);
                    break;
                }
            } while (next_permutation(v.begin(), v.end()));
        }
        probability[possibleStates] = (probability[possibleStates] + probProduct) % MOD;
    }

    for (int subsetMask = 0; subsetMask < (1 << (size * halfH2)); subsetMask++) {
        LLI probProduct = 1;
        for (int j = 0; j < size * halfH2; j++) {
            int rowIdx = j / size + halfH, colIdx = j % size;
            if (subsetMask & (1 << j))
                probProduct = (probProduct * ((LLI) matrix[rowIdx][colIdx] * inv100) % MOD) % MOD;
            else
                probProduct = (probProduct * ((LLI) (100 - matrix[rowIdx][colIdx]) * inv100) % MOD) % MOD;
        }
        int possibleStates = 0;
        for (size_t j = 0; j < maskH.size(); j++) {
            vi v;
            for (int k = 0; k < size; k++) {
                if (!(maskH[j] & (1 << k))) v.push_back(k);
            }
            do {
                int k;
                for (k = 0; k < (int)v.size(); k++) {
                    int a = k * size + v[k];
                    if (!(subsetMask & (1 << a))) break;
                }
                if (k == (int)v.size()) {
                    possibleStates |= (1 << j);
                    break;
                }
            } while (next_permutation(v.begin(), v.end()));
        }
        probability2[possibleStates] = (probability2[possibleStates] + probProduct) % MOD;
    }

    for (int i = 0; i < (int)maskH.size(); i++) {
        for (int j = 0; j < (1 << (int)maskH.size()); j++) {
            if (j & (1 << i))
                probability2[j] = (probability2[j] + probability2[j ^ (1 << i)]) % MOD;
        }
    }

    LLI answer = 0;
