#define MOD 1000000007

int modInverse(int n) {
    int e = MOD-2, r = 1;
    while (e > 0) {
        if (e & 1) r = ((LLI) r * n) % MOD;
        e >>= 1;
        n = ((LLI) n * n) % MOD;
    }
    return r;
}

int main() {
    int n;
    scanf("%d", &n);
    int P[6][6];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) scanf("%d", &P[i][j]);
    }

    vector<int> maskA, maskB;
    int h = (n + 1) / 2;
    int h2 = n - h;
    int inv100 = modInverse(100);

    for (int m = 0; m < (1 << n); m++) {
        int cnt = __builtin_popcount(m);
        if (cnt == h) maskA.push_back(m);
        if (cnt == h2) maskB.push_back(m);
    }

    vector<LLI> probA(1 << (n * h), 0);
    vector<LLI> probB(1 << (n * h2), 0);

    for (int mask = 0; mask < (1 << (n * h)); mask++) {
        LLI p = 1;
        for (int j = 0; j < n * h; j++) {
            int row = j / n, col = j % n;
            if (mask & (1 << j))
                p = (p * ((LLI) P[row][col] * inv100) ) % MOD;
            else
                p = (p * ((LLI) (100 - P[row][col]) * inv100) ) % MOD;
        }
        int stateMask = 0;
        for (size_t j = 0; j < maskA.size(); j++) {
            vi v;
            for (int k = 0; k < n; k++) {
                if (maskA[j] & (1 << k)) v.push_back(k);
            }
            do {
                int k;
                for (k = 0; k < (int)v.size(); k++) {
                    int a = k * n + v[k];
                    if (!(mask & (1 << a))) break;
                }
                if (k == (int)v.size()) {
                    stateMask |= (1 << j);
                    break;
                }
            } while (next_permutation(v.begin(), v.end()));
        }
        probA[stateMask] = (probA[stateMask] + p) % MOD;
    }

    for (int mask = 0; mask < (1 << (n * h2)); mask++) {
        LLI p = 1;
        for (int j = 0; j < n * h2; j++) {
            int row = j / n + h, col = j % n;
            if (mask & (1 << j))
                p = (p * ((LLI) P[row][col] * inv100) ) % MOD;
            else
                p = (p * ((LLI) (100 - P[row][col]) * inv100) ) % MOD;
        }
        int stateMask = 0;
        for (size_t j = 0; j < maskB.size(); j++) {
            vi v;
            for (int k = 0; k < n; k++) {
                if (!(maskB[j] & (1 << k))) v.push_back(k);
            }
            do {
                int k;
                for (k = 0; k < (int)v.size(); k++) {
                    int a = k * n + v[k];
                    if (!(mask & (1 << a))) break;
                }
                if (k == (int)v.size()) {
                    stateMask |= (1 << j);
                    break;
                }
            } while (next_permutation(v.begin(), v.end()));
        }
        probB[stateMask] = (probB[stateMask] + p) % MOD;
    }

    for (int i = 0; i < (int)maskA.size(); i++) {
        for (int j = 0; j < (1 << (int)maskA.size()); j++) {
            if (j & (1 << i))
                probB[j] = (probB[j] + probB[j ^ (1 << i)]) % MOD;
        }
    }

    LLI total = 0;
    int totalStates = 1 << (int)maskA.size();
    for (int i = 0; i < totalStates; i++) {
        total = (total + (LLI)probA[i] * probB[(totalStates - 1) ^ i]) % MOD;
    }

    printf("%lld\n", (MOD + 1 - total) % MOD);
    return 0;
}

