    if (id_map.count(s)) return id_map[s];
    id_map[s] = ++id_counter;
    for (int i=0; i<(1<<n); i++) {
        bitset<128> tmp = s;
        for (int j=0; j<(1<<n); j++) {
            if (!tmp[j]) {
                int x = i & j;
                while (x) {
                    int t = get_bit(x);
                    if (s[j ^ t]) {
                        tmp[j] = 1;
                        break;
                    }
                    x -= t;
                }
            }
        }
        ch[id_map[s]][i] = dfs_bitset(tmp);
    }
    return id_map[s];
}

