#include <bits/stdc++.h>
using namespace std;
const int MOD = 1000000007;

int add_modulo(int x, int y) {
    x += y;
    if (x >= MOD) x -= MOD;
    return x;
}

int mul_modulo(int x, int y) {
    long long res = 1LL * x * y;
    if (res >= MOD) res %= MOD;
    return (int)res;
}

int sub_modulo(int x, int y) {
    x -= y;
    if (x < 0) x += MOD;
    return x;
}

int pow_modulo(int base, int exp) {
    int res = 1;
    while (exp > 0) {
        if (exp & 1) res = mul_modulo(res, base);
        base = mul_modulo(base, base);
        exp >>= 1;
    }
    return res;
}

int get_lowbit(int x) {
    return x & (-x);
}

int n, a[10][10], ch[70010][128], id_count=0, q[10][128], dp[10][70010];
unordered_map<bitset<128>, int> id_map;

int dfs(bitset<128> s) {
    if (id_map.count(s)) return id_map[s];
    id_map[s] = ++id_count;
    for (int i=0; i<(1<<n); i++) {
        bitset<128> tmp = s;
        for (int j=0; j<(1<<n); j++) {
            if (!tmp[j]) {
                int x = i & j;
                while (x) {
                    int t = get_lowbit(x);
                    if (s[j ^ t]) {
                        tmp[j] = 1;
                        break;
                    }
                    x -= t;
                }
            }
        }
        ch[id_map[s]][i] = dfs(tmp);
    }
    return id_map[s];
}

