#include <bits/stdc++.h>
using namespace std;

typedef bitset<128> u99;

constexpr const int mod = 1000000007;
constexpr const int inv =  570000004;
constexpr int add(int a, int b) { return a + b < mod ? a + b : a + b - mod; }
constexpr int sub(int a, int b) { return a < b ? a - b + mod : a - b; }
constexpr int mul(int a, int b) { return 1LL * a * b % mod; }

unordered_map<u99, int> name;
int n, dfn, son[65536][128];
int dfs(u99 s) {
	auto ite = name.find(s);
	if (ite != name.end()) return ite->second;
	int ret = dfn++;
	name[s] = ret;
	for (int i = 0; i != (1 << n); ++i) {
		u99 t = s;
		for (int j = 0; j != (1 << n); ++j) if (!t[j])
			for (int k = i & j; k; k ^= k & -k) if (s[j ^ k & -k]) {
				t[j] = 1;
				break;
			}
		son[ret][i] = dfs(t);
	}
	return ret;
}

int p[7][7], q[7][128], dp[8][65536];

int main() {
	cin >> n;
	dfs(1);
	for (int i = 0; i != n; ++i) for (int j = 0; j != n; ++j) cin >> p[i][j], p[i][j] = mul(p[i][j], inv);
	for (int i = 0; i != n; ++i) for (int j = 0; j != (1 << n); ++j) {
		q[i][j] = 1;
		for (int k = 0; k != n; ++k) q[i][j] = mul(q[i][j], j >> k & 1 ? p[k][i] : sub(1, p[k][i]));
	}
	dp[0][0] = 1;
	for (int i = 0; i != n; ++i) for (int j = 0; j != dfn; ++j) for (int k = 0; k != (1 << n); ++k)
		dp[i + 1][son[j][k]] = add(dp[i + 1][son[j][k]], mul(dp[i][j], q[i][k]));
	u99 res;
	for (int i = 0; i != (1 << n); ++i) res[i] = 1;
	cout << dp[n][name[res]] << endl;
}

#include <bits/stdc++.h>
using namespace std;

using bitset128 = bitset<128>;

constexpr int MOD = 1000000007;
constexpr int INV = 570000004;

int add_mod(int a, int b) {
    int s = a + b;
    return s >= MOD ? s - MOD : s;
}

int sub_mod(int a, int b) {
    int s = a - b;
    return s < 0 ? s + MOD : s;
}

int mul_mod(int a, int b) {
    return (int)((1LL * a * b) % MOD);
}

unordered_map<bitset128, int> index_map;
int node_count, timestamp, children[65536][128];

int dfs(bitset128 state) {
    auto it = index_map.find(state);
    if (it != index_map.end()) return it->second;
    int current_id = timestamp++;
    index_map[state] = current_id;
    for (int mask = 0; mask < (1 << node_count); ++mask) {
        bitset128 new_state = state;
        for (int j = 0; j < (1 << node_count); ++j) {
            if (!new_state[j]) {
                for (int k = mask & j; k; k ^= k & -k) {
                    if (state[j ^ (k & -k)]) {
                        new_state[j] = 1;
                        break;
                    }
                }
            }
        }
        children[current_id][mask] = dfs(new_state);
    }
    return current_id;
}

int p[7][7], q[7][128], dp[8][65536];

int main() {
    int n;
    cin >> n;
    dfs(bitset128(1));
    for (int i = 0; i < n; ++i) for (int j = 0; j < n; ++j) {
        cin >> p[i][j];
        p[i][j] = mul_mod(p[i][j], INV);
    }
    for (int i = 0; i < n; ++i) for (int j = 0; j < (1 << n); ++j) {
        q[i][j] = 1;
        for (int k = 0; k < n; ++k) {
            int val = (j >> k) & 1 ? p[k][i] : sub_mod(1, p[k][i]);
            q[i][j] = mul_mod(q[i][j], val);
        }
    }
    dp[0][0] = 1;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < timestamp; ++j) {
            for (int k = 0; k < (1 << n); ++k) {
                int next_state = children[j][k];
                dp[i + 1][next_state] = add_mod(dp[i + 1][next_state], mul_mod(dp[i][j], q[i][k]));
            }
        }
    }
    bitset128 res;
    for (int i = 0; i < (1 << n); ++i) res[i] = 1;
    cout << dp[n][index_map[res]] << endl;
}

