	}
	ans.A[0][K] = 1; ans.N = K;
	ans = ans*sum[cnt-1][dig[cnt-1] - 1];
	int last = dig[cnt-1];
	for(int i = cnt - 2 ; ~i ; --i){
		for(int j = 0 ; j < dig[i] ; ++j)	
