#include <iostream>
#include <vector>
#include <algorithm>
#include <cstring>
using namespace std;

int main() {
    long long n;
    int k;
    cin >> n >> k;
    vector<int> digits;
    while (n > 0) {
        digits.push_back(n % k);
        n /= k;
    }
    int size = digits.size();
    vector<vector<long long>> matrix(k + 1, vector<long long>(k + 1, 0));
    for (int j = 0; j <= k; ++j) {
        matrix[0][j] = 1;
        matrix[j][j] = 1;
    }
    vector<vector<vector<long long>>> power_matrices(size);
    power_matrices[0] = matrix;
    for (int i = 1; i < size; ++i) {
        vector<vector<long long>> prev = power_matrices[i - 1];
        vector<vector<long long>> now(k + 1, vector<long long>(k + 1, 0));
        for (int x = 0; x <= k; ++x) {
            for (int y = 0; y <= k; ++y) {
                for (int z = 0; z <= k; ++z) {
                    now[x][z] = (now[x][z] + prev[x][y] * matrix[y][z]) % 1000000007;
                }
            }
        }
        power_matrices[i] = now;
    }
    long long result = 1;
    int add = 0;
    for (int i = size - 1; i >= 0; --i) {
        for (int j = 0; j < digits[i]; ++j) {
            for (int x = 0; x <= k; ++x) {
                result = (result * power_matrices[i][(x + add) % k][k]) % 1000000007;
            }
            add = (add + j) % k;
        }
    }
    cout << result % 1000000007 << "\n";
    return 0;
}

