        v.pb(n % k);
        n /= k;
    }
    matr res;
    int shift = 0;
    for (int i = 0; i < sz(v); ++i) {
        shift += v[i];
    }
    for (int i = 0; i < k; ++i) {
        M[i] = matr();
        pref[i] = matr();
        suff[i] = matr();
    }
    for (int i = 0; i < sz(v); ++i) {
        shift -= v[i];
        for (int j = v[i] - 1; j >= 0; --j) {
            if (i == 0) {
                res = get((shift + j) % k) * res;
                continue;
            }
            res = M[(shift + j) % k] * res;
        }
        if (i == 0) {
            for (int i = 0; i < k; ++i) {
                M[i] = matr();
                for (int j = k - 1; j >= 0; --j) {
                    M[i] = get((i + j) % k) * M[i];
                }
            }
        } else {
            for (int i = 0; i < k; ++i) {
                M[i] = matr();
                if (i > 0) {
                    M[i] = pref[i - 1] * M[i];
                }
                M[i] = suff[i] * M[i];
            }
        }
        for (int i = 0; i < k; ++i) {
            pref[i] = (i > 0 ? pref[i - 1] : matr()) * M[i];
        }
        for (int i = k - 1; i >= 0; --i) {
            suff[i] = M[i] * (i + 1 < k ? suff[i + 1] : matr());
        }
    }
    int ans = 0;
    for (int i = 0; i <= k; ++i) {
        ans = (ans + res.a[i][k]) % MOD;
    }
    cout << ans << endl;
    return 0;
}

