const int MAXN = 105;
const int MOD = 1000000007;

ll n; int k;

struct Matrix {
	int a[MAXN][MAXN];
	Matrix() { memset(a, 0, sizeof(a)); }
	void set_identity(int size) {
		for (int i = 1; i <= size; ++i) a[i][i] = 1;
	}
	void print() {
		for (int i = 1; i <= k + 1; ++i) {
			for (int j = 1; j <= k + 1; ++j) {
				printf("%d%c", a[i][j], j == k + 1 ? '\n' : ' ');
			}
		}
	}
};

inline int id(int x, int step) {
	return x <= k ? ((x + step - 1) % k + 1) : x;
}

inline Matrix move_matrix(const Matrix &base, int step) {
	int s = step % k;
	Matrix res;
	memset(res.a, 0, sizeof(res.a));
	for (int i = 1; i <= k + 1; ++i) {
		for (int j = 1; j <= k + 1; ++j) {
			res.a[id(i, s)][id(j, s)] = base.a[i][j];
		}
	}
	return res;
}

inline Matrix multiply(const Matrix &a, const Matrix &b) {
	Matrix res;
	memset(res.a, 0, sizeof(res.a));
	int size = k + 1;
	for (int i = 1; i <= size; ++i) {
		for (int k_idx = 1; k_idx <= size; ++k_idx) {
			if (a.a[i][k_idx]) {
				for (int j = 1; j <= size; ++j) {
					res.a[i][j] = (res.a[i][j] + 1LL * a.a[i][k_idx] * b.a[k_idx][j]) % MOD;
				}
			}
		}
	}
	return res;
}

int main() {
	cin >> n >> k;
	Matrix A[MAXN];
	int ans[MAXN];
	A[0].set_identity(k + 1);
	for (int i = 1; i <= k + 1; ++i) {
		A[0].a[1][i] = 1;
	}
	vector<int> V;
	for (ll len = 0; n; n /= k, V.push_back(n % k), ++len) {
		A[len] = A[len - 1];
		A[len].set_identity(k + 1);
		for (ll p = k, power = 0; p > 0; p >>= 1, ++power) {
			if (p & 1) {
				A[len] = multiply(A[len], move_matrix(A[len - 1], (power ^ 1) << power));
			}
			A[len - 1] = multiply(move_matrix(A[len - 1], 1 << power), A[len - 1]);
		}
	}
	int step = 0;
	ans[k + 1] = 1;
	for (int T = (int)V.size() - 1; T >= 0; --T) {
		int cur = V[T];
		if (cur) {
			int tmp[MAXN];
			for (int t = 0; t < cur; ++t) {
				for (int i = 1; i <= k + 1; ++i) tmp[i] = ans[i], ans[i] = 0;
				Matrix B = move_matrix(A[T], t + step);
				for (int i = 1; i <= k + 1; ++i) {
					for (int j = 1; j <= k + 1; ++j) {
						ans[i] = (ans[i] + 1LL * tmp[j] * B.a[i][j]) % MOD;
					}
				}
			}
		}
		step += cur;
	}
	int res = 0;
	for (int i = 1; i <= k + 1; ++i) res = (res + ans[i]) % MOD;
	printf("%d\n", res);
	return 0;
}

