}

namespace matrix {
    template<int N, int M>
    class Mat {
    public:
        int data[N][M];

        void reset() {
            memset(data, 0, sizeof(data));
        }

        void set_identity() {
            reset();
            for (int i = 0; i < min(N, M); ++i)
                data[i][i] = 1;
        }

        Mat<M, N> transpose() const {
            Mat<M, N> t;
            t.reset();
            for (int i = 0; i < M; ++i)
                for (int j = 0; j < N; ++j)
                    t[i][j] = data[j][i];
            return t;
        }

        const int* get_row(int r) const {
            return data[r];
        }

        int* get_row(int r) {
            return data[r];
        }

        Mat<N, M> add(const Mat<N, M>& other) const {
            Mat<N, M> res;
            for (int i = 0; i < N; ++i)
                for (int j = 0; j < M; ++j)
                    res[i][j] = sum_mod(data[i][j], other[i][j]);
            return res;
        }

        Mat<N, M> multiply_by(int scalar) const {
            Mat<N, M> res = *this;
            for (int i = 0; i < N; ++i)
                for (int j = 0; j < M; ++j)
                    res[i][j] = mult_mod(res[i][j], scalar);
            return res;
        }

        template<int X>
        friend Mat<N, M> multiply(const Mat<N, X>& a, const Mat<X, M>& b) {
            Mat<N, M> out;
            out.reset();
            for (int i = 0; i < N; ++i) {
                for (int j = 0; j < X; ++j) {
                    if (a[i][j]) {
                        for (int k = 0; k < M; ++k) {
                            out[i][k] = sum_mod(out[i][k], mult_mod(a[i][j], b[j][k]));
                        }
                    }
                }
            }
            return out;
        }
    };
}

