    PER(i,len-1,0) {
        REP(j,dig[i]) {
            mat_mul(A[i][(j+x)%kb],ans,ans);
        }
        x=(x+dig[i])%kb;
    }
    int res=0;
    for(int i=0;i<kb;i++) {
        res=(res+ans[i][0])%MOD;
    }
    printf("%d\n",res+1);
    return 0;
}

