            fac[i] = fac[i - 1] * i % mod;
        }
        inv[n] = power(fac[n], mod - 2);
        for (int i = n - 1; i >= 0; --i) {
            inv[i] = inv[i + 1] * (i + 1) % mod;
        }

        vector<int> list;
        for (int i = 0; i < n; ++i) {
            if (n & (1 << i))
                list.push_back(i);
