#define ms(s, n) memset(s, n, sizeof(s))
#define FOR(i, a, b) for (int i = (a); i < (b); i++)
#define all(a) (a).begin(), (a).end()
#define pb push_back
#define mp make_pair
typedef long long ll;
typedef vector<int> vi;

void transform_fft(int a[], int n, int p, bool inv) {
    int logn = __lg(n);
    for (int i = 0; i < logn; i++) {
        for (int mask = 0; mask < n; mask++) {
            if (mask & (1 << i)) {
                int prev_mask = mask ^ (1 << i);
                if (!inv) {
                    a[mask] = (a[mask] + a[prev_mask]) % p;
                } else {
                    a[mask] = (a[mask] - a[prev_mask] + p) % p;
                }
            }
        }
    }
}

vector<int> pow_conv(const vector<int>& a, int k, int p) {
    int n = (int)a.size();
    if (k == 1) return a;
    if (k % 2 == 1) {
        vector<int> prev = pow_conv(a, k - 1, p);
        vector<int> res(n, 0);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j + i < n; j++) {
                res[i + j] = (res[i + j] + (long long)prev[i] * a[j]) % p;
            }
        }
        return res;
    } else {
        vector<int> half = pow_conv(a, k / 2, p);
        vector<int> res(n, 0);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j + i < n; j++) {
                res[i + j] = (res[i + j] + (long long)half[i] * half[j]) % p;
            }
        }
        return res;
    }
}

vector<int> subset_power_alt(vector<int> a, int k, int p) {
    const int LOGN = 19;
    static int fa[LOGN][1 << LOGN], fc[LOGN][1 << LOGN];
    int n = a.size();
    while (n & (n - 1)) n++;
    for (int i = 0; i < LOGN; i++) {
        for (int j = 0; j < n; j++) {
            fa[i][j] = (i == __builtin_popcount(j)) ? (j < (int)a.size() ? a[j] : 0) : 0;
        }
        transform_fft(fa[i], n, p, false);
    }
    vector<int> res(n, 0);
    for (int i = 0; i < n; i++) {
        vector<int> v(LOGN);
        for (int j = 0; j < LOGN; j++) v[j] = fa[j][i];
        v = pow_conv(v, k, p);
        for (int j = 0; j < LOGN; j++) fc[j][i] = v[j];
    }
    for (int i = 0; i < LOGN; i++) {
        transform_fft(fc[i], n, p, true);
        for (int j = 0; j < n; j++) {
            if (__builtin_popcount(j) == i) {
                res[j] = fc[i][j];
            }
        }
    }
    return res;
}

const int MAXN = 1e6 + 5;
int n, k, p;
int fact[MAXN], inv_fact[MAXN];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> k >> p;
    int mask_n = n;
    for (int i = 0; i <= n; i++) {
        if ((n & i) == i) {
            int msk = 0;
            for (int j = 0; j < 20; j++) {
                msk <<= 1;
                if (n & (1 << j)) msk |= (i & (1 << j)) ? 1 : 0;
            }
            // process msk as needed
            mask_n = max(mask_n, msk);
        }
    }
    if (n & 1) {
        cout << pow(k, n) % p << "\n";
        return 0;
    }
    fact[0] = 1;
    for (int i = 1; i < MAXN; i++) fact[i] = (long long)fact[i - 1] * i % p;
    inv_fact[MAXN - 1] = pow(fact[MAXN - 1], p - 2, p);
    for (int i = MAXN - 2; i >= 0; i--) inv_fact[i] = (long long)inv_fact[i + 1] * (i + 1) % p;
    vector<int> a(mask_n + 1, 0);
    for (int i = 0; i <= mask_n; i++) a[i] = inv_fact[i]; // simplified
    int res = pow(k, n) % p;
    a = subset_power_alt(a, k, p);
    int subtract_value = (long long)a[mask_n] * fact[n] % p;
    res = (res - subtract_value + p) % p;
    cout << res << "\n";
    return 0;
}

