#include <bits/stdc++.h>
using namespace std;

const int Maxn = 1 << 19 | 5;
int n, k, p, maxi, ct[Maxn], f[Maxn];
int tmp1[20][Maxn], tmp2[20][Maxn], tmp3[20][Maxn];
long long pp;
long long t[20][Maxn];
long long fac[Maxn], inv[Maxn];
long long fast_pow(long long x, long long y)
{
    long long ans = 1, now = x;
    while (y)
    {
        if (y & 1) ans = ans * now % p;
        now = now * now % p;
        y >>= 1;
    }
    return ans;
}
void init(void)
{
    fac[0] = 1;
    for (int i = 1; i <= maxi; i++)
        fac[i] = fac[i - 1] * i % p;
    inv[maxi] = fast_pow(fac[maxi], p - 2);
    for (int i = maxi - 1; i >= 0; i--)
        inv[i] = inv[i + 1] * (i + 1) % p;
}
int lower(int x)
{
    int tmp = 1;
    for (; tmp < x; tmp <<= 1);
    return tmp;
}
void FWT(int *now, int len, bool type = false)
{
    long long *T = t[0];
    for (int i = 0; i < len; i ++) T[i] = now[i];
    if (type)
        for (int i = 1; i < len; i <<= 1)
            for (int j = 0; j < len; j += (i << 1))
                for (int k = j; k < i + j; k++)
                    T[i + k] -= T[k];
    else
        for (int i = 1; i < len; i <<= 1)
            for (int j = 0; j < len; j += (i << 1))
                for (int k = j; k < i + j; k++)
                    T[i + k] += T[k];
    for (int i = 0; i < len; i ++) {
        now[i] = T[i] % p;
        if (now[i] < 0) now[i] += p;
    }
}
inline void __a (long long &x) { x >= pp ? x -= pp : x; }
void multi(void)
{
    for (int j = 0; j <= 19; j++)
    {
        memset(tmp1[j], 0, sizeof(int[maxi + 1]));
        memset(t[j], 0, sizeof(long long[maxi + 1]));  
    }
    for (int j = 0; j <= maxi; j++)
        tmp1[ct[j]][j] = f[j];
    for (int j = 0; j <= 19; j++)
        FWT(tmp1[j], maxi + 1);
    for (int q = 0; q <= 19; q++)
        for (int l = 0; q + l <= 19; l++)
            for (int s = 0; s <= maxi; s++)
                __a(t[q + l][s] += 1ll * tmp1[q][s] * tmp2[l][s]);
    for (int q = 0; q <= 19; q++)
        for (int s = 0; s <= maxi; s++)
            tmp3[q][s] = t[q][s] % p;
    for (int j = 0; j <= 19; j++)
        FWT(tmp3[j], maxi + 1, true);
    for (int j = 0; j <= maxi; j++)
        f[j] = tmp3[ct[j]][j];
}
void multi2(void)
{
    static int tmp[20][Maxn];
    for (int i = 0; i <= 19; i++)
        memset(t[i], 0, sizeof(long long[maxi + 1]));
    for (int q = 0; q <= 19; q++)
        for (int l = 0; q + l <= 19; l++)
            for (int s = 0; s <= maxi; s++)
                __a(t[q + l][s] += 1ll * tmp2[q][s] * tmp2[l][s]);
    for (int q = 0; q <= 19; q++)
        for (int s = 0; s <= maxi; s++)
            tmp[q][s] = t[q][s] % p;
    for (int i = 0; i <= 19; i++)
        FWT(tmp[i], maxi + 1, true);
    for (int i = 0; i <= 19; i++)
        memset(tmp2[i], 0, sizeof(int[maxi + 1]));
    for (int i = 0; i <= maxi; i++)
        tmp2[ct[i]][i] = tmp[ct[i]][i];
    for (int i = 0; i <= 19; i++)
        FWT(tmp2[i], maxi + 1);
}
int main()
{
    scanf("%d%d%d", &n, &k, &p);
    pp = 1ll * p * p;
    if (n & 1)
    {
        printf("%lld", fast_pow(k, n));
        return 0;
    }
    f[0] = 1;
    maxi = lower(n + 1) - 1;
    init();
    for (int i = 0; i <= maxi; i++)
        ct[i] = __builtin_popcount(i);
    for (int i = 0; i <= maxi; i++)
        tmp2[ct[i]][i] = inv[i];
    for (int i = 0; i <= 19; i++)
        FWT(tmp2[i], maxi + 1);
    int res_k = k;
    while (k)
    {
        cerr << k << endl;
        if (k & 1) multi();
        k >>= 1;
        if (k) multi2();
    }
    printf("%lld", (fast_pow(res_k, n) - fac[n] * f[n] % p + p) % p);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int MAX_SIZE = 1 << 19 | 5;
int total_numbers, exponent, modulus, max_bit, count[MAX_SIZE], f_array[MAX_SIZE];
int tmp1_arr[20][MAX_SIZE], tmp2_arr[20][MAX_SIZE], tmp3_arr[20][MAX_SIZE];
long long power_product;
long long t_arr[20][MAX_SIZE];
long long factorial[MAX_SIZE], inv_factorial[MAX_SIZE];

long long fastExponentiation(long long base, long long exp) {
    long long result = 1, current = base;
    while (exp) {
        if (exp & 1) result = result * current % modulus;
        current = current * current % modulus;
        exp >>= 1;
    }
    return result;
}

void initialize() {
    factorial[0] = 1;
    for (int i = 1; i <= max_bit; i++)
        factorial[i] = factorial[i - 1] * i % modulus;
    inv_factorial[max_bit] = fastExponentiation(factorial[max_bit], modulus - 2);
    for (int i = max_bit - 1; i >= 0; i--)
        inv_factorial[i] = inv_factorial[i + 1] * (i + 1) % modulus;
}

int get_lower_power(int x) {
    int power = 1;
    while (power < x) power <<= 1;
    return power;
}

void transformFWT(int *array, int length, bool inverse = false) {
    long long *temp = t_arr[0];
    for (int i = 0; i < length; i++) temp[i] = array[i];
    if (inverse)
        for (int i = 1; i < length; i <<= 1)
            for (int j = 0; j < length; j += (i << 1))
                for (int k = j; k < i + j; k++)
                    temp[i + k] -= temp[k];
    else
        for (int i = 1; i < length; i <<= 1)
            for (int j = 0; j < length; j += (i << 1))
                for (int k = j; k < i + j; k++)
                    temp[i + k] += temp[k];
    for (int i = 0; i < length; i++) {
        array[i] = temp[i] % modulus;
        if (array[i] < 0) array[i] += modulus;
    }
}

inline void adjust_mod(long long &x) { x >= power_product ? x -= power_product : x; }

void multiply() {
    for (int j = 0; j <= 19; j++) {
        memset(tmp1_arr[j], 0, sizeof(int[max_bit + 1]));
        memset(t_arr[j], 0, sizeof(long long[max_bit + 1]));
    }
    for (int j = 0; j <= max_bit; j++)
        tmp1_arr[count[j]][j] = f_array[j];
    for (int j = 0; j <= 19; j++)
        transformFWT(tmp1_arr[j], max_bit + 1);
    for (int q = 0; q <= 19; q++)
        for (int l = 0; q + l <= 19; l++)
            for (int s = 0; s <= max_bit; s++)
                adjust_mod(t_arr[q + l][s] += 1LL * tmp1_arr[q][s] * tmp2_arr[l][s]);
    for (int q = 0; q <= 19; q++)
        for (int s = 0; s <= max_bit; s++)
            tmp3_arr[q][s] = t_arr[q][s] % modulus;
    for (int j = 0; j <= 19; j++)
        transformFWT(tmp3_arr[j], max_bit + 1, true);
    for (int j = 0; j <= max_bit; j++)
        f_array[j] = tmp3_arr[count[j]][j];
}

void multiplySecond() {
    static int tmp[20][MAX_SIZE];
    for (int i = 0; i <= 19; i++)
        memset(t_arr[i], 0, sizeof(long long[max_bit + 1]));
    for (int q = 0; q <= 19; q++)
        for (int l = 0; q + l <= 19; l++)
            for (int s = 0; s <= max_bit; s++)
                adjust_mod(t_arr[q + l][s] += 1LL * tmp2_arr[q][s] * tmp2_arr[l][s]);
    for (int q = 0; q <= 19; q++)
        for (int s = 0; s <= max_bit; s++)
            tmp[q][s] = t_arr[q][s] % modulus;
    for (int i = 0; i <= 19; i++)
        transformFWT(tmp[i], max_bit + 1, true);
    for (int i = 0; i <= 19; i++)
        memset(tmp2_arr[i], 0, sizeof(int[max_bit + 1]));
    for (int i = 0; i <= max_bit; i++)
        tmp2_arr[count[i]][i] = tmp[count[i]][i];
    for (int i = 0; i <= 19; i++)
        transformFWT(tmp2_arr[i], max_bit + 1);
}

int main() {
    scanf("%d%d%d", &total_numbers, &exponent, &modulus);
    power_product = 1LL * modulus * modulus;
    if (total_numbers & 1) {
        printf("%lld", fastExponentiation(exponent, total_numbers));
        return 0;
    }
    f_array[0] = 1;
    max_bit = get_lower_power(total_numbers + 1) - 1;
    initialize();
    for (int i = 0; i <= max_bit; i++)
        count[i] = __builtin_popcount(i);
    for (int i = 0; i <= max_bit; i++)
        tmp2_arr[count[i]][i] = inv_factorial[i];
    for (int i = 0; i <= 19; i++)
        transformFWT(tmp2_arr[i], max_bit + 1);
    int res_exponent = exponent;
    while (exponent) {
        if (exponent & 1) multiply();
        exponent >>= 1;
        if (exponent) multiplySecond();
    }
    printf("%lld", (fastExponentiation(res_exponent, total_numbers) - factorial[total_numbers] * f_array[total_numbers] % modulus + modulus) % modulus);
    return 0;
}

