#include <bits/stdc++.h>
#define inf 17446744073709551616ull
#define ull unsigned long long
using namespace std;

ull mod, dp[18][250005];
ull fac[250005], inv[250005];
ull n, k;

ull qpow(ull a, ull b) {
    ull res = 1ULL, base = a;
    while (b) {
        if (b & 1ULL) {
            res *= base;
            res %= mod;
        }
        base *= base;
        base %= mod;
        b >>= 1ULL;
    }
    return res;
}

ull cal(int a, int b) {
    return (((fac[a] * inv[b]) % mod) * inv[a - b]) % mod;
}

ull compute() {
    int i, j, l;
    fac[0] = 1ULL;
    for (i = 1; i <= n; i++) {
        fac[i] = (fac[i - 1] * (ull)(i)) % mod;
    }
    inv[n] = qpow(fac[n], mod - 2ULL);
    for (i = n - 1; i >= 0; i--) {
        inv[i] = (inv[i + 1] * (ull)(i + 1)) % mod;
    }
    for (i = 1; i <= n; i++) {
        dp[1][i] = inv[i];
    }
    ull answer = dp[1][n] * cal(k, 1) % mod;
    int t = min(17, (int)k);
    for (i = 2; i <= t; i++) {
        for (j = n; j; j = (j - 1) & n) {
            for (l = j; l; l = (l - 1) & j) {
                dp[i][j] += dp[i - 1][j ^ l] * inv[l];
                if (dp[i][j] > inf)
                    dp[i][j] %= mod;
            }
            dp[i][j] %= mod;
        }
        answer += dp[i][n] * cal(k, i);
        answer %= mod;
    }
    answer *= fac[n];
    answer %= mod;
    return answer;
}

