using ll = long long;
ll qpow(ll a,ll b)
{
    ll ret = 1;
    while (b)
    {
        if (b & 1) ret = ret * a % P;
        a = a * a % P;b >>= 1;
    }
    return ret;
}
inline int lowbit(int x) {return x & -x;}
ll fac[N],inv[N],dp[26][N];
ll dfs(int cur,int msk)
{
    if (dp[cur][msk] != -1) return dp[cur][msk];
    if (!msk)
    {
        dp[cur][msk] = fac[n];
        for (int i = 1;i <= cur;i++)
            dp[cur][msk] = dp[cur][msk] * (kk - i + 1) % P;
        return dp[cur][msk];
    }
    dp[cur][msk] = 0;int tmp = msk - lowbit(msk);
    for (int i = tmp;i > 0;i = (i - 1) & tmp)
        dp[cur][msk] = (dp[cur][msk] + inv[msk - i] * dfs(cur + 1,i)) % P;
    dp[cur][msk] = (dp[cur][msk] + inv[msk] * dfs(cur + 1,0)) % P;
    return dp[cur][msk];
}
int main ()
{
    ios::sync_with_stdio(false);
    cin >> n >> kk >> P;ll ans = qpow(kk,n);
    if (n & 1) {cout << ans << endl;return 0;}
    fac[0] = 1;
    for (int i = 1;i <= n;i++) fac[i] = fac[i - 1] * i % P;
    inv[n] = qpow(fac[n],P - 2);
    for (int i = n;i > 0;--i) inv[i - 1] = inv[i] * i % P;
    memset(dp,-1,sizeof(dp));ans = (ans - dfs(0,n) + P) % P;
    cout << ans << endl;
    return 0;
}
// 非卡常做法需要用FWT
// 卡常做法: 每次强制将Ai规定为含有msk的lowbit的那一个，最后当msk=0时用排列乘回来

#include <bits/stdc++.h>
using namespace std;
const int N = 250005;
int n, kk, P;
using ll = long long;

ll fast_pow(ll base, ll exp) {
    ll result = 1;
    while (exp > 0) {
        if (exp & 1) result = result * base % P;
        base = base * base % P;
        exp >>= 1;
    }
    return result;
}

inline int get_lowbit(int x) {
    return x & -x;
}

ll factorial[N], inv_factorial[N], dp_table[26][N];

ll recursive_dp(int current, int mask) {
    if (dp_table[current][mask] != -1) return dp_table[current][mask];
    if (mask == 0) {
        dp_table[current][mask] = factorial[n];
        for (int i = 1; i <= current; i++)
            dp_table[current][mask] = dp_table[current][mask] * (kk - i + 1) % P;
        return dp_table[current][mask];
    }
    ll &res = dp_table[current][mask];
    res = 0;
    int tmp_mask = mask - get_lowbit(mask);
    for (int sub_mask = tmp_mask; sub_mask > 0; sub_mask = (sub_mask - 1) & tmp_mask)
        res = (res + inv_factorial[mask - sub_mask] * recursive_dp(current + 1, sub_mask)) % P;
    res = (res + inv_factorial[mask] * recursive_dp(current + 1, 0)) % P;
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> kk >> P;
    ll answer = fast_pow(kk, n);
    if (n & 1) {
        cout << answer << "\n";
        return 0;
    }
    factorial[0] = 1;
    for (int i = 1; i <= n; i++) factorial[i] = factorial[i - 1] * i % P;
    inv_factorial[n] = fast_pow(factorial[n], P - 2);
    for (int i = n; i > 0; --i) inv_factorial[i - 1] = inv_factorial[i] * i % P;
    memset(dp_table, -1, sizeof(dp_table));
    answer = (answer - recursive_dp(0, n) + P) % P;
    cout << answer << "\n";
    return 0;
}

