LL power(LL base, LL exp) {
    LL res = 1;
    while (exp > 0) {
        if (exp & 1) res = res * base % mod;
        base = base * base % mod;
        exp >>= 1;
    }
    return res;
}

inline int getLowbit(int x) {
    return x & (-x);
}

LL factorials[MAXN], inv_factorials[MAXN], memo[26][MAXN];

LL solve(int level, int mask) {
    if (memo[level][mask] != -1) return memo[level][mask];
    if (mask == 0) {
        memo[level][mask] = factorials[total_n];
        for (int i = 1; i <= level; i++)
            memo[level][mask] = memo[level][mask] * (max_kk - i + 1) % mod;
        return memo[level][mask];
    }
    LL &res = memo[level][mask];
    res = 0;
    int tmp_mask = mask - getLowbit(mask);
    for (int sub_mask = tmp_mask; sub_mask > 0; sub_mask = (sub_mask - 1) & tmp_mask)
        res = (res + inv_factorials[mask - sub_mask] * solve(level + 1, sub_mask)) % mod;
    res = (res + inv_factorials[mask] * solve(level + 1, 0)) % mod;
    return res;
}

