}

LL factorials[MAX_SIZE], inv_factorials[MAX_SIZE], cache[26][MAX_SIZE];

LL recurse(int level, int mask) {
    if (cache[level][mask] != -1) return cache[level][mask];
    if (mask == 0) {
        cache[level][mask] = factorials[n_value];
        for (int i = 1; i <= level; i++)
            cache[level][mask] = cache[level][mask] * (k_value - i + 1) % mod_value;
        return cache[level][mask];
