int n, k, i, j, u, v, M = 1000000009;
long long factorials[MAXN], inv_factorials[MAXN], dp_results[30][22], a_data[18][MAXN], b_results[MAXN];

long long fast_power(long long base, long long exp) {
    long long res = 1, cur = base;
    while (exp > 0) {
        if (exp & 1) res = (res * cur) % M;
        cur = (cur * cur) % M;
        exp >>= 1;
    }
    return res;
}

int main() {
    scanf("%d %d %d", &n, &k, &M);
    if (n % 2 != 0) {
        cout << fast_power(k, n) << "\n";
        return 0;
    }
    factorials[0] = 1;
    for (i = 1; i <= n; ++i) {
        factorials[i] = (factorials[i - 1] * i) % M;
    }
    inv_factorials[n] = fast_power(factorials[n], M - 2);
    for (i = n - 1; i >= 0; --i) {
        inv_factorials[i] = (inv_factorials[i + 1] * (i + 1)) % M;
    }
    int half_n = n >> 1;
    for (i = 0; i <= half_n; ++i) {
        int popcnt = __builtin_popcount(i);
        a_data[popcnt][i] = inv_factorials[i * 2];
    }
    for (i = 0; i < 17; ++i)
        for (j = 0; j < 17; ++j)
            for (u = 0; u < (1 << 17); ++u)
                if ((u >> j) & 1)
                    a_data[i][u] += a_data[i][u ^ (1 << j)];
    for (i = 0; i < 17; ++i)
        for (u = 0; u < (1 << 17); ++u)
            a_data[i][u] %= M;
    int popcnt_half = __builtin_popcount(half_n);
    for (i = 0; i < (1 << 17); ++i) {
        memset(dp_results, 0, sizeof(dp_results));
        dp_results[0][0] = 1;
        for (j = 1; j <= k; ++j) {
            for (u = 0; u <= 17; ++u) {
                for (v = 0; v + u <= 17; ++v) {
                    dp_results[j][u + v] += a_data[u][i] * dp_results[j - 1][v];
                }
                if ((u & 7) == 0) {
                    for (v = 0; v <= 17; ++v) {
                        dp_results[j][v] %= M;
                    }
                }
            }
            for (v = 0; v <= 17; ++v) {
                dp_results[j][v] %= M;
            }
        }
        b_results[i] = dp_results[k][popcnt_half];
    }
    for (i = 0; i < 17; ++i)
        for (j = 0; j < (1 << 17); ++j)
            if ((j >> i) & 1)
                b_results[j] -= b_results[j ^ (1 << i)];
    long long answer = ((fast_power(k, n * 2) - b_results[n] * factorials[n * 2]) % M + M) % M;
    cout << answer << "\n";
    return 0;
}

