    for(int i=0;i<=n;i++){
        int K_copy=K;
        memset(buffer2,0,sizeof buffer2); buffer2[0]=1;
        while(K_copy){
            if(K_copy&1) array_multiply(buffer2,buffer2,matrix[i]);
            array_multiply(matrix[i],matrix[i],matrix[i]);
            K_copy>>=1;
        }
        memcpy(matrix[i],buffer2,sizeof buffer2);
    }
    inverse_transform(matrix);
    int answer=(total - 1ll*matrix[n][N]*factorial[original_n])%mod;
