int main() {
    ios::sync_with_stdio(false);
    cin >> n >> m >> mod;

    C[0][0] = 1;
    for (int i = 1; i <= n; ++i) {
        C[i][0] = 1;
        for (int j = 1; j <= n; ++j) {
            C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % mod;
        }
    }

    w[0] = 1;
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= i; ++j) {
            ll current = C[i - 1][j - 1] * w[j - 1] % mod * w[i - j] % mod;
            w[i] = (w[i] + current * (i + 1)) % mod;
            ll part1 = (dp[j - 1] * w[i - j] + w[j - 1] * dp[i - j]) % mod;
            ll part2 = (i - j) * (i - j + 1) / 2 + j * (j - 1) / 2;
            ll contribution = (C[i - 1][j - 1] * part1) % mod * (i + 1) % mod;
            contribution = (contribution + current * part2) % mod;
            dp[i] = (dp[i] + contribution) % mod;
        }
    }

    w2[0][0] = 1;
    for (int i = 1; i <= n + 1; ++i) {
        for (int k = 0; k <= m; ++k) {
