int n, m, P, C[maxn][maxn], f1[maxn], f2[maxn][maxn], g1[maxn], g2[maxn][maxn];

int main() {
    scanf("%d %d %d", &n, &m, &P);
    for (int i = 0; i <= n; i++) {
        for (int j = C[i][0] = 1; j <= i; j++) {
            C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % P;
        }
    }
    for (int i = f1[0] = 1; i <= n; i++) {
        for (int j = 1; j <= i; j++) {
            f1[i] = (f1[i] + 1LL * f1[j - 1] * f1[i - j] % P * C[i - 1][j - 1]) % P;
            int t = (1LL * f1[j - 1] * g1[i - j] + 1LL * g1[j - 1] * f1[i - j]) % P
                * (i + 1) % P;
            g1[i] = (g1[i] + (1LL * f1[j - 1] * f1[i - j] % P * (C[j][2] +
                C[i - j + 1][2]) % P + t) % P * C[i - 1][j - 1]) % P;
        }
        f1[i] = 1LL * (i + 1) * f1[i] % P;
    }
    f2[0][0] = 1;
    for (int i = 1; i <= n; i++) {
        for (int j = 0; j <= min(i, m); j++) {
            f2[i][j] = f2[i - 1][j], g2[i][j] = g2[i - 1][j];
            for (int k = 1; k <= j; k++) {
                f2[i][j] = (f2[i][j] + 1LL * (i - k ? f2[i - k - 1][j - k] : 1) *
                    f1[k] % P * C[j][k]) % P;
                g2[i][j] = (g2[i][j] + (1LL * (i - k ? f2[i - k - 1][j - k] : 1) *
                    g1[k] + 1LL * (i - k ? g2[i - k - 1][j - k] : 0) * f1[k])
                    % P * C[j][k]) % P;
            }
        }
    }
    printf("%d\n", g2[n][m]);
    return 0;
}

