int main() {
    scanf("%d %d %d", &total_nodes, &max_edges, &prime_mod);
    for (int i = 0; i <= total_nodes; i++) {
        for (int j = 0; j <= i; j++) {
            if (j == 0) binom[i][j] = 1;
            else binom[i][j] = (binom[i - 1][j - 1] + binom[i - 1][j]) % prime_mod;
        }
    }
    f1_arr[0] = 1;
    for (int i = 1; i <= total_nodes; i++) {
        f1_arr[i] = 0;
        g1_arr[i] = 0;
        for (int j = 1; j <= i; j++) {
            f1_arr[i] = (f1_arr[i] + (long long)f1_arr[j - 1] * f1_arr[i - j] % prime_mod * binom[i - 1][j - 1]) % prime_mod;
            int temp = ((long long)f1_arr[j - 1] * g1_arr[i - j] + (long long)g1_arr[j - 1] * f1_arr[i - j]) % prime_mod;
            temp = (temp * (i + 1)) % prime_mod;
            g1_arr[i] = (g1_arr[i] + ((long long)f1_arr[j - 1] * f1_arr[i - j] % prime_mod * (binom[j][2] + binom[i - j + 1][2]) + temp) % prime_mod * binom[i - 1][j - 1]) % prime_mod;
        }
        f1_arr[i] = (long long)(i + 1) * f1_arr[i] % prime_mod;
    }
    g2_arr[0][0] = 1;
    for (int i = 1; i <= total_nodes; i++) {
        for (int j = 0; j <= min(i, max_edges); j++) {
            f2_arr[i][j] = f2_arr[i - 1][j];
            g2_arr[i][j] = g2_arr[i - 1][j];
            for (int k = 1; k <= j; k++) {
                long long temp_f = (i - k ? f2_arr[i - k - 1][j - k] : 1);
                f2_arr[i][j] = (f2_arr[i][j] + temp_f * f1_arr[k] % prime_mod * binom[j][k]) % prime_mod;
                long long temp_g = (i - k ? f2_arr[i - k - 1][j - k] : 1);
                long long g_part = ((long long)temp_g * g1_arr[k] + (long long)(i - k ? g2_arr[i - k - 1][j - k] : 0) * f1_arr[k]) % prime_mod;
                g2_arr[i][j] = (g2_arr[i][j] + g_part * binom[j][k]) % prime_mod;
            }
        }
    }
    printf("%d\n", g2_arr[total_nodes][max_edges]);
    return 0;
}

