const int MAX = 511;
int dwu[MAX][MAX];
int dp1[MAX];
int dp2[MAX][MAX];
int dp3[MAX][MAX];
int count[MAX];

int main() {
  ios_base::sync_with_stdio(0);
  cin.tie(0);
  cout << fixed << setprecision(11);
  cin >> n >> m >> P;
  R(i,n + 1) R(j,i + 1){
    if(j == 0){
      dwu[i][j] = 1;
    }else{
      dwu[i][j] = dwu[i-1][j];
      add_mod(dwu[i][j], dwu[i-1][j-1]);
    }
  }

  dp1[0] = 0;
  count[0] = 1;
  R(i,m+1) if(i){
    R(j,i){
      int temp = 0;
      add_mod(temp, multiply(dp1[j], count[i-j-1]));
      add_mod(temp, multiply(dp1[i-j-1], count[j]));
      multiply_self(temp, j + 1);
      add_mod(temp, multiply(multiply(count[i-j-1], count[j]), j * (j + 1) / 2));
      multiply_self(temp, dwu[i-1][j]);
      debug(temp, count[i-j-1], count[j], j * (j + 1) / 2, dwu[i-1][j]);
      add_mod(dp1[i], temp);
      temp = dwu[i-1][j];
      multiply_self(temp, count[j]);
      multiply_self(temp, count[i-j-1]);
      multiply_self(temp, j + 1);
      add_mod(count[i], temp);
    }
    add_mod(count[i], count[i]);
    add_mod(dp1[i], dp1[i]);
    debug(i, count[i], dp1[i]);
  }

  dp2[0][0] = 1;
  dp3[0][0] = 0;
  R(i,n+1) R(j,m+1) R(k,m+1) if(j + k <= m && i + k + 1 <= n + 1){
    int temp = dp2[i][j];
    multiply_self(temp, dwu[m - j][k]);
    multiply_self(temp, count[k]);
    int temp3 = dp3[i][j];
