using namespace std;
int n,m,md;
int c[505][505], dpf[505][505], dpr[505][505];
long long f[505], rst[505], sum(long long x) {
    return (x * (x + 1LL)) / 2;
}
int main() {
    scanf("%d%d%d", &n, &m, &md);
    for (int i = 0; i <= n; i++) {
        c[i][0] = 1;
        for (int j = 1; j <= i; j++) {
            c[i][j] = (c[i - 1][j] + c[i - 1][j - 1]) % md;
        }
    }
    for (int i = 0; i < n; i++) {
        for (int k = 0; k <= i; k++) {
            long long current = c[i][k];
            long long crst = 0;
            if (k > 0) {
                crst = (crst * f[k - 1] + current * rst[k - 1]) % md;
                current = (current * f[k - 1]) % md;
            }
            if (k < i) {
                crst = (crst * f[i - k - 1] + current * rst[i - k - 1]) % md;
                current = (current * f[i - k - 1]) % md;
            }
            rst[i] = (rst[i] + crst * (i + 2) + current * (sum(k) + sum(i - k))) % md;
            f[i] = (f[i] + (i + 2) * current) % md;
        }
    }
    dpf[0][0] = 1;
    for (int i = 1; i <= n; i++) {
        for (int j = 0; j <= i && j <= m; j++) {
            dpf[i][j] = dpf[i - 1][j];
            dpr[i][j] = dpr[i - 1][j];
            for (int k = 1; k <= j; k++) {
                int prev = i - k;
                if (prev > 0) prev--;
                if (j - k <= prev) {
                    long long temp1 = (dpr[prev][j - k] * f[k - 1] + dpf[prev][j - k] * rst[k - 1]) % md;
                    long long temp2 = (dpf[prev][j - k] * f[k - 1]) % md;
