const int N = 505;

int n, m, md;

inline int add(int x, int y) {
    x += y;
    if (x >= md) x -= md;
    return x;
}

inline int sub(int x, int y) {
    x -= y;
    if (x < 0) x += md;
    return x;
}

inline int mul(int x, int y) { return 1ll * x * y % md; }

inline int fpow(int x, int y) {
    int ans = 1;
    while (y) {
        if (y & 1) ans = mul(ans, x);
        y >>= 1; x = mul(x, x);
    }
    return ans;
}

int fac[N], inv[N], f[N], g[N], dp[N][N][2], dp2[N][N][2];

inline int C(int n, int m) {
    return mul(fac[n], mul(inv[m], inv[n - m]));
}

int main() {
    read(n); read(m); read(md);
    fac[0] = 1;
    for (int i = 1; i <= n; i++) fac[i] = mul(fac[i - 1], i);
    inv[n] = fpow(fac[n], md - 2);
    for (int i = n; i >= 1; i--) inv[i - 1] = mul(inv[i], i);
    f[0] = 0; g[0] = 1;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= i; j++) {
            int now = mul(C(i - 1, j - 1), i + 1);
            g[i] = add(g[i], mul(mul(g[j - 1], g[i - j]), now));
            f[i] = add(f[i], mul(mul(f[j - 1], g[i - j]), now));
            f[i] = add(f[i], mul(mul(g[j - 1], f[i - j]), now));
            f[i] = add(f[i], mul(mul(C(i - 1, j - 1), mul(g[j - 1], g[i - j])), (j - 1) * j / 2 + (i - j) * (i - j + 1) / 2));
        }
        // fprintf(stderr, "f[%d] = %d, g[%d] = %d\n", i, f[i], i, g[i]);
    }
    dp[0][0][1] = 0; dp2[0][0][1] = 1;
    for (int i = 1; i <= n; i++) {
        for (int j = 0; j <= i; j++) {
            dp[i][j][1] = add(dp[i - 1][j][0], dp[i - 1][j][1]);
            dp2[i][j][1] = add(dp2[i - 1][j][0], dp2[i - 1][j][1]);
            for (int k = 1; k <= j; k++) {
                dp[i][j][0] = add(dp[i][j][0], mul(C(j, k), mul(dp2[i - k][j - k][1], f[k])));
                dp[i][j][0] = add(dp[i][j][0], mul(C(j, k), mul(dp[i - k][j - k][1], g[k])));
                dp2[i][j][0] = add(dp2[i][j][0], mul(C(j, k), mul(dp2[i - k][j - k][1], g[k])));
            }
        }
    }
    print(add(dp[n][m][0], dp[n][m][1]), '\n');
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, m, md;
    cin >> n >> m >> md;
    vector<unsigned long long> fac(n + 1, 1), inv(n + 1, 1), f(n + 1, 0), g(n + 1, 1);
    for (int i = 1; i <= n; ++i) {
        fac[i] = fac[i - 1] * i % md;
    }
    auto fpow = [&](int x, int y) {
        unsigned long long res = 1, base = x;
        while (y > 0) {
            if (y & 1) res = res * base % md;
            base = base * base % md;
            y >>= 1;
        }
        return res;
    };
    inv[n] = fpow(fac[n], md - 2);
    for (int i = n; i >= 1; --i) {
        inv[i - 1] = inv[i] * i % md;
    }
    auto C = [&](int n, int r) {
        return fac[n] * inv[r] % md * inv[n - r] % md;
    };
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= i; ++j) {
            int now = (int)(C(i - 1, j - 1) * (long long)(i + 1) % md);
            g[i] = (g[i] + (long long)g[j - 1] * g[i - j] % md * now) % md;
            f[i] = (f[i] + (long long)f[j - 1] * g[i - j] % md * now) % md;
            f[i] = (f[i] + (long long)g[j - 1] * f[i - j] % md * now) % md;
            int add_val = ((j - 1) * j / 2 + (i - j) * (i - j + 1) / 2);
            f[i] = (f[i] + (long long)C(i - 1, j - 1) * g[j - 1] % md * g[i - j] % md * add_val) % md;
        }
    }
    vector<vector<vector<int>>> dp(n + 1, vector<vector<int>>(m + 1, vector<int>(2, 0)));
    vector<vector<vector<int>>> dp2(n + 1, vector<vector<int>>(m + 1, vector<int>(2, 0)));
    dp[0][0][1] = 0; dp2[0][0][1] = 1;
    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j <= i; ++j) {
            dp[i][j][1] = (dp[i - 1][j][0] + dp[i - 1][j][1]) % md;
            dp2[i][j][1] = (dp2[i - 1][j][0] + dp2[i - 1][j][1]) % md;
            for (int k = 1; k <= j; ++k) {
                int c = (int)(C(j, k));
                int val1 = (int)((long long)dp2[i - k][j - k][1] * f[k] % md);
                int val2 = (int)((long long)dp[i - k][j - k][1] * g[k] % md);
                dp[i][j][0] = (dp[i][j][0] + (long long)c * val1) % md;
                dp[i][j][0] = (dp[i][j][0] + (long long)c * val2) % md;
                dp2[i][j][0] = (dp2[i][j][0] + (long long)c * val2) % md;
            }
        }
    }
    cout << (dp[n][m][0] + dp[n][m][1]) % md << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, m, md;
    scanf("%d %d %d", &n, &m, &md);
    vector<unsigned long long> factorial(n + 1, 1), inv_factorial(n + 1, 1);
    for (int i = 1; i <= n; ++i) {
        factorial[i] = factorial[i - 1] * i % md;
    }
    auto fast_pow = [&](int base, int exp) {
        unsigned long long result = 1, b = base;
        while (exp > 0) {
            if (exp & 1) result = result * b % md;
            b = b * b % md;
            exp >>= 1;
        }
        return result;
    };
    inv_factorial[n] = fast_pow(factorial[n], md - 2);
    for (int i = n; i >= 1; --i) {
        inv_factorial[i - 1] = inv_factorial[i] * i % md;
    }
    auto comb = [&](int a, int b) {
        return factorial[a] * inv_factorial[b] % md * inv_factorial[a - b] % md;
    };
    vector<int> g(n + 1, 1), f(n + 1, 0);
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= i; ++j) {
            int now = (int)(comb(i - 1, j - 1) * (long long)(i + 1) % md);
            g[i] = (g[i] + (long long)g[j - 1] * g[i - j] % md * now) % md;
            f[i] = (f[i] + (long long)f[j - 1] * g[i - j] % md * now) % md;
            f[i] = (f[i] + (long long)g[j - 1] * f[i - j] % md * now) % md;
            int add_val = ((j - 1) * j / 2 + (i - j) * (i - j + 1) / 2);
            f[i] = (f[i] + (long long)comb(i - 1, j - 1) * g[j - 1] % md * g[i - j] % md * add_val) % md;
        }
    }
    vector<vector<vector<int>>> dp(n + 1, vector<vector<int>>(m + 1, vector<int>(2, 0)));
    vector<vector<vector<int>>> dp2(n + 1, vector<vector<int>>(m + 1, vector<int>(2, 0)));
    dp[0][0][1] = 0; dp2[0][0][1] = 1;
    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j <= i; ++j) {
            dp[i][j][1] = (dp[i - 1][j][0] + dp[i - 1][j][1]) % md;
            dp2[i][j][1] = (dp2[i - 1][j][0] + dp2[i - 1][j][1]) % md;
            for (int k = 1; k <= j; ++k) {
                int c = (int)(comb(j, k));
                int val1 = (int)((long long)dp2[i - k][j - k][1] * f[k] % md);
                int val2 = (int)((long long)dp[i - k][j - k][1] * g[k] % md);
