template <typename T>
T abs_value(T x) { return (x < 0) ? (-x) : x; }

cat mod_pow(cat base, cat exp, cat mod) {
	if(exp <= 0) return 1;
	cat result = 1;
	cat cur = base % mod;
	while(exp > 0) {
		if(exp & 1) result = result * cur % mod;
		cur = cur * cur % mod;
		exp >>= 1;
	}
	return result;
}

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(nullptr);
	cout.tie(nullptr);
	cout << fixed << setprecision(10);
	int N, M;
	cat mod;
	cin >> N >> M >> mod;
	vector<cat> fac(N+1, 1), inv_fac(N+1, 1);
	for(int i = 1; i <= N; i++) {
		fac[i] = fac[i-1] * i % mod;
		inv_fac[i] = inv_fac[i-1] * mod_pow(i, mod-2, mod) % mod;
	}
	vector<cat> cnt(M+1, 0);
	vector<cat> sum(M+1, 0);
	cnt[0] = 1;
	for(int m = 1; m <= M; m++) {
		for(int k = 0; k < m; k++) {
			cat c_left = cnt[k] * inv_fac[k] % mod;
			cat c_right = cnt[m-1-k] * inv_fac[m-1-k] % mod;
			cat s_left = sum[k] * inv_fac[k] % mod;
			cat s_right = sum[m-1-k] * inv_fac[m-1-k] % mod;
			cnt[m] = (cnt[m] + c_left * c_right % mod * (m+1)) % mod;
			sum[m] = (sum[m] + (s_left * c_right + c_left * s_right + s_left * s_right) % mod * (m+1)) % mod;
			sum[m] = (sum[m] + c_left * c_right % mod * (k*(k+1)+(m-k)*(m-k-1))/2) % mod;
		}
		cnt[m] = cnt[m] * fac[m-1] % mod;
		sum[m] = sum[m] * fac[m-1] % mod;
	}
	vector<vector<cat>> cnt_ans(N+1, vector<cat>(M+1, 0));
	vector<vector<cat>> sum_ans(N+1, vector<cat>(M+1, 0));
	cnt_ans[0][0] = 1;
	for(int i = 1; i <= N; i++) {
		for(int j = 0; j <= min(i, M); j++) {
			cnt_ans[i][j] = cnt_ans[i-1][j];
			sum_ans[i][j] = sum_ans[i-1][j];
			if(j == i) {
				cnt_ans[i][j] = (cnt_ans[i][j] + cnt[i] * inv_fac[i]) % mod;
				sum_ans[i][j] = (sum_ans[i][j] + sum[i] * inv_fac[i]) % mod;
			}
			for(int k = 1; k <= min(j, i-1); k++) {
				cat c = cnt[k] * inv_fac[k] % mod;
				cat s = sum[k] * inv_fac[k] % mod;
				cnt_ans[i][j] = (cnt_ans[i][j] + cnt_ans[i-1-k][j-k] * c) % mod;
				sum_ans[i][j] = (sum_ans[i][j] + (sum_ans[i-1-k][j-k] * c + cnt_ans[i-1-k][j-k] * s)) % mod;
			}
		}
	}
	cat final_res = sum_ans[N][M] * fac[M] % mod;
	cout << final_res << "\n";
}

