#include <bits/stdc++.h>
using namespace std;
const int MAX=510;
typedef pair<int,int> Pair;
#define make_pair mp
#define first fi
#define second se

int total_n, total_m, modulus, C[MAX][MAX];
Pair dp_table[MAX][MAX];

int add_mod(int a, int b) {
    return a + b >= modulus ? a + b - modulus : a + b;
}

Pair operator+(const Pair &a, const Pair &b) {
    return make_pair(add_mod(a.fi, b.fi), add_mod(a.se, b.se));
}

Pair operator*(const Pair &a, const Pair &b) {
    long long fi_part = 1LL * a.fi * b.fi % modulus;
    long long se_part = (1LL * a.fi * b.se + 1LL * a.se * b.fi) % modulus;
    return make_pair((int)fi_part, (int)se_part);
}

int sum_range(int left, int right) {
    return (left + right) * (right - left + 1) / 2;
}

int main() {
#ifdef LOCAL
    freopen("a.in", "r", stdin);
    freopen("a.out", "w", stdout);
#endif
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> total_n >> total_m >> modulus;
    for (int i = 0; i < MAX; i++) {
        C[i][0] = 1;
        for (int j = 1; j <= i; j++) {
            C[i][j] = add_mod(C[i - 1][j], C[i - 1][j - 1]);
        }
    }
    for (int i = 0; i <= total_n; i++) {
        dp_table[i][0] = make_pair(1, 0);
        for (int j = 1; j <= i && j <= total_m; j++) {
            if (i != j) {
                for (int k = 1; k <= i; k++) {
                    dp_table[i][j] = dp_table[i][j] + dp_table[k - 1][k - 1] * dp_table[i - k][j - k + 1] * make_pair(C[j][k - 1], 0);
                }
            } else {
                for (int k = 1; k <= i; k++) {
                    auto term1 = dp_table[k - 1][k - 1];
                    auto term2 = dp_table[i - k][i - k];
                    auto comb = make_pair(C[i - 1][k - 1], 0);
                    int factor = i + 1 - sum_range(1, k) + sum_range(k + 1, i) - k * (i - k);
                    auto factor_pair = make_pair(factor, 0);
                    dp_table[i][j] = dp_table[i][j] + term1 * term2 * comb * factor_pair;
                }
            }
        }
    }
    cout << dp_table[total_n][total_m].second;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
const int MAX_SIZE=510;
typedef pair<int,int> PairType;
#define create_pair mp
#define get_first fi
#define get_second se

int n_value, m_value, mod_value, binom[MAX_SIZE][MAX_SIZE];
PairType dp_array[MAX_SIZE][MAX_SIZE];

int sumInterval(int start, int end) {
    return (start + end) * (end - start + 1) / 2;
}

int addModulo(int a, int b) {
    int sum = a + b;
    if (sum >= mod_value) sum -= mod_value;
    return sum;
}

PairType operator+(const PairType &a, const PairType &b) {
    return create_pair(addModulo(a.get_first, b.get_first), addModulo(a.get_second, b.get_second));
}

PairType operator*(const PairType &a, const PairType &b) {
    long long first_part = 1LL * a.get_first * b.get_first % mod_value;
    long long second_part = (1LL * a.get_first * b.get_second + 1LL * a.get_second * b.get_first) % mod_value;
    return create_pair((int)first_part, (int)second_part);
}

int main() {
#ifdef LOCAL
    freopen("a.in", "r", stdin);
    freopen("a.out", "w", stdout);
#endif
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n_value >> m_value >> mod_value;
    for (int i=0; i<MAX_SIZE; i++) {
        binom[i][0]=1;
        for (int j=1; j<=i; j++) {
            binom[i][j]=addModulo(binom[i-1][j], binom[i-1][j-1]);
        }
    }
    for (int i=0; i<=n_value; i++) {
        dp_array[i][0]=create_pair(1,0);
        for (int j=1; j<=i && j<=m_value; j++) {
            if (i!=j) {
                for (int k=1; k<=i; k++) {
                    dp_array[i][j]=dp_array[i][j]+dp_array[k-1][k-1]*dp_array[i-k][j-k+1]*create_pair(binom[j][k-1],0);
                }
            } else {
                for (int k=1; k<=i; k++) {
                    auto t1=dp_array[k-1][k-1];
                    auto t2=dp_array[i-k][i-k];
                    auto comb=create_pair(binom[i-1][k-1],0);
                    int factor= i+1 - sumInterval(1,k) + sumInterval(k+1,i) - k*(i-k);
                    auto factor_pair=create_pair(factor,0);
                    dp_array[i][j]=dp_array[i][j]+t1*t2*comb*factor_pair;
                }
            }
        }
    }
    cout<<dp_array[n_value][m_value].get_second;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
const int MAXN=510;
typedef pair<int,int> Pair;
#define pair_make make_pair
#define first_elem first
#define second_elem second

int N, M, MOD, C[MAXN][MAXN];
Pair DP[MAXN][MAXN];

int sumRange(int l, int r) {
    return (l + r) * (r - l + 1) / 2;
}

int addMod(int a, int b) {
    int res=a+b;
    if(res>=MOD) res-=MOD;
    return res;
}

Pair operator+(const Pair &a, const Pair &b) {
    return pair_make(addMod(a.first_elem, b.first_elem), addMod(a.second_elem, b.second_elem));
}

Pair operator*(const Pair &a, const Pair &b) {
    long long fi_part=1LL*a.first_elem*b.first_elem%MOD;
    long long se_part=(1LL*a.first_elem*b.second_elem+1LL*a.second_elem*b.first_elem)%MOD;
    return pair_make((int)fi_part, (int)se_part);
}

int main() {
#ifdef LOCAL
    freopen("a.in","r",stdin);
    freopen("a.out","w",stdout);
#endif
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin>>N>>M>>MOD;
    for(int i=0;i<MAXN;i++) {
        C[i][0]=1;
        for(int j=1;j<=i;j++) C[i][j]=addMod(C[i-1][j], C[i-1][j-1]);
    }
    for(int i=0;i<=N;i++) {
        DP[i][0]=pair_make(1,0);
        for(int j=1;j<=i && j<=M;j++) {
            if(i!=j) {
                for(int k=1;k<=i;k++)
                    DP[i][j]=DP[i][j]+DP[k-1][k-1]*DP[i-k][j-k+1]*pair_make(C[j][k-1],0);
            } else {
                for(int k=1;k<=i;k++) {
                    auto t1=DP[k-1][k-1];
                    auto t2=DP[i-k][i-k];
                    auto comb=pair_make(C[i-1][k-1],0);
                    int fct= i+1 - sumRange(1,k) + sumRange(k+1,i) - k*(i-k);
                    auto fct_pair=pair_make(fct,0);
                    DP[i][j]=DP[i][j]+t1*t2*comb*fct_pair;
                }
            }
        }
    }
    cout<<DP[N][M].second_elem;
    return 0;
}

