        arrF[i] = arrF[i] * (i + 1) % P;
    }
    memset(dpF, 0, sizeof(dpF));
    memset(dpG, 0, sizeof(dpG));
    dpF[0][0] = 1;
    for(int j = 0; j <= n; ++j) dpF[0][j] = 1;
    for(int i = 1; i <= m; ++i) {
        dpF[i][i] = arrF[i];
        dpG[i][i] = arrG[i];
        for(int j = i + 1; j <= n; ++j) {
            dpF[i][j] = dpF[i][j - 1];
            dpG[i][j] = dpG[i][j - 1];
            for(int l = 1; l <= i; ++l) {
                dpF[i][j] = (dpF[i][j] + dpF[i - l][j - 1 - l] * arrF[l] % P * comb(i, l)) % P;
                dpG[i][j] = (dpG[i][j] + (dpG[i - l][j - 1 - l] * arrF[l] % P + dpF[i - l][j - 1 - l] * arrG[l] % P) * comb(i, l)) % P;
            }
        }
    }
    printf("%lld\n", dpG[m][n]);
    return 0;
}

