    for (int i = 0; i <= m; ++i) {
      c[i][0] = 1;
      for (int j = 1; j <= i; ++j) {
        c[i][j] = c[i - 1][j - 1];
        update_mod(c[i][j], c[i - 1][j]);
      }
    }
  }
  {
    dp[0] = T(1);
    for (int k = 1; k <= m; ++k) {
      auto &current = dp[k];
      current = T(0);
      for (int i = 0; i < k; ++i) {
        auto x = dp[i] * dp[k - i - 1];
        x = x * T(c[k - 1][i]);
        for (int j = 0; j < k; ++j) {
          auto y = x * T(1 + (j == i), abs(i - j));
          current = current + y;
        }
      }
      eprintf("%d %d\n", dp[k].cnt, dp[k].sum);
    }
  }
  for (int i = 0; i <= n; ++i) {
    for (int j = 0; j <= m; ++j) {
      pdp[i][j] = T(0);
    }
  }
  pdp[0][0] = T(1);
  for (int i = 0; i < n; ++i) {
    for (int j = 0; j <= m; ++j) {
      auto current = pdp[i][j];
      if (!current.cnt && !current.sum) continue;
      {
        auto &next = pdp[i + 1][j];
        next = next + current;
      }
      for (int k = 1; j + k <= m && i + k <= n; ++k) {
        auto &next = pdp[min(n, i + k + 1)][j + k];
        next = next + current * dp[k] * T(c[m - j][k]);
      }
    }
  }
  printf("%d\n", pdp[n][m].sum);
}

