int M;
int spow(int a, int b) {
  int r = 1;
  while (b) {
    if (b % 2) {
      r = r * a % M;
    }
    a = a * a % M;
    b /= 2;
  }
  return r;
}
int Inv(int a) {
  int b = M - 2;
  int r = 1;
  while (b) {
    if (b % 2) {
      r = r * a % M;
    }
    a = a * a % M;
    b /= 2;
  }
  return r;
}
int f(int c, int p) {
  if (p == 0) { return 1; }
  return spow(c + 1, p - 1) * (c + 1 - p) % M;
}
const int N = 515;
int newt[N][N];
int inv_newt[N][N];
int32_t main() {

  ios_base::sync_with_stdio(0);
  cout << fixed << setprecision(10);
  cerr << fixed << setprecision(10);
  cin.tie(0);
  //double beg_clock = 1.0 * clock() / CLOCKS_PER_SEC;

  int c, p;
  cin>>c>>p>>M;
  REP (i, c + 2) {
    newt[i][i] = newt[i][0] = 1;
    RE (j, i - 1) {
      newt[i][j] = (newt[i - 1][j] + newt[i - 1][j - 1]) % M;
    }
  }
  debug(newt[10][5]);
  REP (i, c + 2) {
    REP (j, c + 2) {
      inv_newt[i][j] = Inv(newt[i][j]);
    }
  }
  int ans = f(c, p);
//   int ans = (c + 1 - p);
//   RE (i, p - 1) {
//     ans = ans * (c + 1) % M;
//   }
//   RE (i, p) {
//     ans = ans * 2 % M;
//   }
  debug(ans);
  ans = ans * spow(2, p) % M;
  int sum_e = 0;
  RE (i, p) {
    int e = 0;
//     RE (j, i - 1) {
//       e = (e + newt[c + 1 - j][i - 1 - j] * inv_newt[c + 1][i - 1]) % M;
//     }
    RE (w, i - 1) {
      int zioms = newt[i - 1][w] * f(w, w) % M * f(c - w - 1, i - 1 - w) % M;
      debug(zioms, i, w);
      zioms = zioms * Inv(spow(c + 1, i - 1)) % M;

      // zioms - pstwo, ze na ustalony pzedzial [l, r] jest zapelniony, a po jego bokach nie
      e = (e + w * (w + 1) / 2 * zioms) % M;
    }
    debug(i, e, e * ans % M);
    sum_e = (sum_e + e) % M;
  }
  cout<<ans * sum_e % M<<"\n";

























  return 0;
}

