            comb[i][j] = (comb[i-1][j-1] + comb[i-1][j]) % mod;
        }
    }

    vector<ll> f(n+1, 0), g(n+1, 0);
    f[0] = 1;
    for (int i=1; i<=n; i++) {
        for (int j=0; j<i; j++) {
            int k = i - j - 1;
            f[i] = (f[i] + (ll)f[j] * f[k] % mod * (i+1) % mod * comb[i-1][j]) % mod;
            g[i] = (g[i] + (ll)g[j] * f[k] % mod * (i+1) % mod * comb[i-1][j]) % mod;
            g[i] = (g[i] + (ll)f[j] * g[k] % mod * (i+1) % mod * comb[i-1][j]) % mod;
            g[i] = (g[i] + (ll)f[j] * f[k] % mod * comb[i-1][j] % mod * (((j*(j+1))/2) + ((k*(k+1))/2))) % mod;
        }
    }

    vector<vector<vector<int>>> dp(n+2, vector<vector<int>>(n+2, vector<int>(2,0)));
    dp[0][0][1] = 1;

    for (int i=0; i<n; i++) {
        for (int j=0; j<=i; j++) {
            dp[i+1][j][1] = (dp[i+1][j][1] + dp[i][j][0] + dp[i][j][1]) % mod;
            for (int k=0; k<=n-i; k++) {
                int ni = i + k;
                int nj = j + k;
                if (ni <= n && nj <= n) {
                    ll val = (ll)dp[i][j][1] * f[k] % mod * comb[j+k][j] % mod;
                    dp[ni][nj][0] = (dp[ni][nj][0] + val) % mod;
                }
            }
        }
    }

    ll result=0;
    for (int j=0; j<n; j++) {
        for (int i=0; i<=j; i++) {
            int rem = m - (j - i + 1);
            if (rem < 0) continue;
            for (int k=0; k<=rem; k++) {
                ll temp = (ll)g[j - i + 1] * dp[i-1][k][1] % mod * dp[n - j][rem - k][1] % mod * comb[m][rem] % mod * comb[rem][k] % mod;
                result = (result + temp) % mod;
            }
        }
    }
    cout << result << "\n";
    return 0;
}

