long long compute_value_alt(long long x, long long y, int v1, int v2)
{
	long long state_id = x * 10000 + v1 * 100 + v2;
	if (memo_map.count(state_id))
		return memo_map[state_id];

  long long &res = memo_map[state_id];
  long long diff = abs(x - y);
  if (diff - C[v1][r] * C[v2][r] > minimal_difference) {
    return res = 0;
  }
  if (v1 < r || v2 < r) {
    if (v1 >= cntA[v1 + v2] && v2 >= cntB[v1 + v2]) {
      int sum = v1 + v2;
      v1 -= cntA[sum];
      v2 -= cntB[sum];
      return res = C[v1 + v2][v1]; 
    }
    return res = 0;
  }
	res = 0;
	char c = s[v1 + v2 - 1];
	if (c != 'B')
	{
		long long delta1 = C[v1][r] - C[v1 - 1][r];
